/* المرحلة ٤: الغرس في أرض عربية (١٠–١٣ سنة) — عمّان · سيناريوهات كاملة */
window.SD.stages.push({id:4,icon:'🌳',color:'#C9962E',name:'الغرسُ في أرضٍ عربية',years:'١٠–١٣ سنة',place:'عمّان — الأردن',
intro:'الجذور تلمس أرضها: بيت الجد وشجرة الزيتون، حلقة الفجر عند الشيخ محمود، صدمة اللغة ثم فتحها، جبل نيبو الذي يرى منه فلسطين، وعهد المئذنة في الثالثة عشرة. هنا يتحول الحب إلى التزام.',
eps:[
{n:45,t:'بيتُ الزيتونة',ic:'🏡',age:'١٠ سنوات',loc:'بيت الجد — عمّان',corner:'parents',goal:'بر الجد وحكمة المجالسة: للكبار مقام ومجلس وقبلة رأس ويد',chars:['العائلة','الجد عبد القادر','الجدة خديجة','الأقارب'],
scenes:[
{h:'م١ · خارجي/داخلي — بيت الجد، لحظة الوصول',d:'سيارة الأجرة تقف أمام بيت حجري بشرفة عتيقة وعريشة عنب. الباب يفتح قبل أن يطرقوه — الجدة خديجة تخرج بذراعين مفتوحتين وزغرودة توقظ الحارة، خلفها الجد يتوكأ عصاه ودمعتاه تسبقان كلماته. أحضان لا تنتهي: الجدة تقبّل شام وتشمها كوردة، الجد يرفع يوسف رغم ظهره.',dlg:[['الجدة خديجة','(بين الزغاريد) جاؤوا! يا حارتَنا جاؤوا! عشرُ سنينَ يا أيوب… عشرُ سنينَ وأنا أفرشُ فراشَكم كلَّ عيدٍ وأطويه!'],['الجد','(يمسك كتفي صلاح الدين ويتأمله طويلاً)… أطولُ مما في الشاشة. وأثقلُ عوداً. (يهمس) أهلاً بحاملِ الاسمِ في أرضِ الحكاية.']],vo:'عشرُ سنينَ من المكالماتِ لم تهيئني لدفءِ ذلك الحضن. الشاشاتُ يا أصدقائي تنقلُ الوجوه… أما رائحةُ الجدةِ — خبزٌ وزعترٌ وحنان — فلا ينقلُها إلا اللقاء.'},
{h:'م٢ · داخلي — مجلس البيت، درس المقامات',d:'مجلس عربي بفرشات مطرزة. الأقارب يتوافدون للسلام. صلاح الدين يراقب ويتعلم في الوقت الحقيقي: أبوه ينحني يقبّل رأس عمه الأكبر ويده. القهوة المرة تدور — أيوب يعلّم ابنه همساً.',dlg:[['أيوب','(هامساً) انظر وتعلم: القهوةُ تُقدَّمُ باليمينِ للأكبرِ أولاً مهما كان جالساً في آخرِ المجلس. والداخلُ يسلمُ على الجالسين، والصغيرُ على الكبير.'],['صلاح الدين','(يهمس) ولماذا قبَّلتَ رأسَ عمي؟'],['أيوب','لأن رسولَ اللهِ ﷺ قال: ليس منا من لم يرحمْ صغيرَنا ويعرفْ شرفَ كبيرِنا. الرأسُ الذي شابَ في الطاعةِ… يُقبَّلُ منه الموضعُ الذي شاب.'],['صلاح الدين','(يقوم فجأة من مكانه، يمشي نحو جده المنشغل بالحديث، وينحني ويقبّل رأسه وكوفيته — المجلس كله يصمت ثم يضج بالاستحسان)'],['الجد','(ممسكاً بيده، للمجلس بفخر لا يخفى) رأيتم؟… مانشستر ما أخذتْ منه شيئاً. الأصلُ يا جماعة… الأصلُ إذا صحَّ، صحَّ الغرسُ في كلِّ أرض.']]},
{h:'م٣ · خارجي — حديقة البيت، طقس الزيتونة',d:'الغروب يذهّب الحديقة. الجد يقود صلاح الدين بيده إلى الزيتونة العتيقة — جذع ملتوٍ كأنه ضفائر، وأوراق فضية تلمع. تحتها دلو ماء معدني قديم.',dlg:[['الجد','هذه التي رأيتَها في الشاشة… سلِّمْ عليها، فهي أقدمُ فردٍ في العائلة! غرسَها أبي بيدَيهِ من نوى زيتونِ بلادِنا قربَ القدس، وسقيتُها أنا سبعين عاماً. (يرفع الدلو بيدين مرتجفتين ويضعه في يدي حفيده) واليوم… تسقيها يدٌ ثالثة.'],['صلاح الدين','(يحمل الدلو بهيبة من يحمل أمانة، ويسكب الماء ببطء حول الجذع) بسمِ الله… (يلتفت لجده) جدي، وهل تعرفُ الشجرةُ من يسقيها؟'],['الجد','(يضع كفه على الجذع) الشجرُ يا حبيبي لا ينسى: لا أرضاً خرجَ منها، ولا يداً سقتْه. مثلُنا تماماً… ولهذا نحن أمةٌ لا تنسى قدسَها ولو طالَ الزمن. الزيتونُ شاهدُنا.']],vo:'دلوُ ماءٍ صار طقسي اليومي إلى آخرِ عمرِ جدي. وتعلمتُ تحتَ تلك الشجرةِ أولَ قوانينِ الأرض: من سقى شيئاً بيدِه… أحبَّهُ بقلبِه. اسقوا شيئاً كلَّ يومٍ يا أصدقائي — شجرةً، أو علماً، أو أخاً صغيراً.'},
{h:'م٤ · داخلي — المطبخ، مملكة الجدة',d:'ليل. الجدة خديجة تعجن وتحكي — صلاح الدين ويوسف على طاولة المطبخ يراقبان خبز الطابون يتشكل.',dlg:[['الجدة','…وكان أبوكِ يا مريم يسرقُ العجينَ نيئاً! (تضحك) تعالَ يا صلاح الدين — ضعْ كفَّكَ هكذا في العجين. هيك… بالبركة. الخبزُ يا ستي ما بيطيبْ إلا بشغلتين: نارٍ هادية… وإيدٍ بتحب.'],['صلاح الدين','(يغرس كفه في العجين الدافئ) نارٌ هادئة ويدٌ تحب… (يبتسم لنفسه) يا جدتي، هذه وصفةُ أمي في تحفيظي القرآن!'],['الجدة','(تتوقف عن العجن وتنظر لمريم بدمعة فخر) سمعتِ يا بنتي؟… ربَّيتِ فيلسوفاً يشبِّهُ القرآنَ بالخبز. (تقبّل رأسه) وصدقَ واللهِ — كلاهما قوتُ القلب.']]},
{h:'م٥ · خارجي — سطح البيت، ليلة النجوم الأولى',d:'فرشات على السطح — تقليد الصيف. العائلة تحت سماء صافية مذهلة: نجوم لا تحصى ودرب التبانة ظاهر. صلاح الدين مستلقٍ بين جده وأبيه، فمه مفتوح دهشة.',dlg:[['صلاح الدين','كلُّ هذه كانت فوقَنا في مانشستر… ولا نراها؟!'],['الجد','السماءُ واحدةٌ يا حبيبي… لكنَّ مدنَ الضبابِ تحجبُها. (يشير بعصاه) هناك… النجمُ القطبي: دليلُ المسافرين من قبلِ البوصلات. جدُّكَ الأكبرُ كان يقول: من عرفَ نجمَهُ… ما ضاعَ ولو بعُدَ الدرب.'],['صلاح الدين','(يخرج بوصلة توم من جيبه ويوجهها نحو الشمال ثم يبتسم ويلتفت غرباً) نجمي هناك يا جدي… خلفَ تلك التلال. أنتَ تعرف.'],['الجد','(صمت… ثم يمد يده في العتمة ويمسك يد حفيده) أعرف… ناما يا أولاد. غداً المدرسة. وطريقُ النجومِ البعيدة… يبدأ من فجرِ الغد.']],vo:'أولُ ليلةٍ في أرضِ العائلة: نمتُ تحتَ ألفِ نجم، ويدي في يدِ جدي، وبوصلتي في جيبي تشيرُ إلى مانشستر… وقلبي يشيرُ إلى القدس. وفهمتُ أن الإنسانَ يمكنُ أن يملكَ أكثرَ من وطنٍ في قلبِه — بشرطِ أن يعرفَ نجمَه.'}],
msg:'اعرف شرف كبيرك: قبلة الرأس وأدب المجلس وسقيا يد — فمن سقى شيئاً بيده أحبه بقلبه، ومن عرف نجمه ما ضاع.',apply:'تعلّم أدبين من آداب مجالس الكبار وطبقهما اليوم: قبّل رأس جدك (أو أكبر أهلك) وقدّم له الشاي بيمينك قبل الجميع.'},

{n:46,t:'لغةٌ تتكسّرُ على لساني',ic:'🗣️',age:'١٠ سنوات',loc:'مدرسة عمّان',corner:'academy',goal:'الصبر على تعلم الفصحى: لغة القرآن تستحق العرق — والسخرية لا توقف الجاد',chars:['صلاح الدين','الأستاذ فؤاد','زملاء الصف','الجد'],
scenes:[
{h:'م١ · داخلي — الصف الخامس، مدرسة عمّان',d:'أول حصة لغة عربية. الأستاذ فؤاد — نظارة وابتسامة ولهجة فصيحة — يطلب من التلميذ الجديد التعريف بنفسه. صلاح الدين يقف واثقاً (عربيته البيتية جيدة… يظن).',dlg:[['صلاح الدين','أنا اسمي صلاح الدين… أنا جيتُ من مانشستر يعني أتيتُ… إحنا كنا — نحنُ كان عندنا بيت و… (يخلط العامية بالفصحى بالإنجليزية) and we الحمد لله…'],['الصف','(ضحكات تتصاعد من المقاعد الخلفية — تلميذ يقلد لكنته هامساً: «آي كنتُ آي جيت»)'],['صلاح الدين','(يجلس ووجهه يحترق… بطل مانشستر الذي خطب على المنابر، يتلعثم في بلاد لسانه)']],vo:'مفارقةٌ لم أحسبْ لها حساباً: في مانشستر كنتُ «العربي» الذي يفخرُ بلغتِه… وفي عمّان صرتُ «الإنجليزي» الذي يضحكُ الصفُّ من لسانِه. الغربةُ يا أصدقائي ليست مكاناً… أحياناً تكونُ لساناً.'},
{h:'م٢ · داخلي — غرفته في بيت الجد، ليلة الدموع',d:'صلاح الدين تحت اللحاف يكتم بكاءه. مريم تدخل بهدوء وتجلس على طرف السرير — تعرف هذا المشهد من ليالي مانشستر الأولى.',dlg:[['صلاح الدين','(منفجراً) أريدُ العودةَ لمانشستر! هناك كنتُ أفهمُ وأُفهِم! هنا حتى الرياضياتُ بالعربيةِ الصعبة… وقواعدُ النحو؟ فاعلٌ ومفعول؟ لماذا يرفعون وينصبون؟! أنا غبيٌّ هنا يا ماما!'],['مريم','(تسحب اللحاف عن وجهه بلطف) انظرْ في عيني: أنتَ لستَ غبياً… أنتَ مهاجرٌ جديد. وهل نسيتَ؟ عشتُ المشهدَ نفسَهُ معكوساً قبل خمسِ سنين: طفلٌ يبكي لأن الإنجليزيةَ تتكسرُ على لسانِه… فمن صارَ يخطبُ بها بعد سنتين؟'],['صلاح الدين','(يمسح دموعه)… أنا؟'],['مريم','فما الذي تغير؟ اللغةُ الجديدةُ جبلٌ — وأنتَ يا حبيبي… متسلقُ جبالٍ محترف. نامِ الآن، وغداً نبدأ من الدرجةِ الأولى.']]},
{h:'م٣ · داخلي — غرفة المعلمين، احتضان الأستاذ فؤاد',d:'الأستاذ فؤاد استدعاه بعد أيام — ليس للعقاب. على مكتبه دفتر جديد أخضر.',dlg:[['الأستاذ فؤاد','سمعتُ من ضحكوا عليك… وأريدُكَ أن تحفظَ عني ثلاثاً: الأولى — من يحاولُ يخطئ، ومن لا يخطئُ لا يتعلم؛ فأخطاؤكَ أشرفُ عندي من صمتِ الخائفين. الثانية — أنتَ لا تتعلمُ «مادةً»… أنتَ تفتحُ خزانةَ القرآنِ والمتنبي وصلاحِ الدينِ الذي تحملُ اسمَه: كلُّهم ينتظرونكَ خلفَ هذا الباب. الثالثة — (يدفع الدفتر الأخضر) هذا دفترُ كنوزِك: ثلاثُ كلماتٍ فصيحةٍ كلَّ يوم، تكتبُها وتستعملُها في جملةٍ تقولُها فعلاً. ثلاثٌ فقط — لكن كلَّ يوم.'],['صلاح الدين','(يمسك الدفتر — يتذكر لوحة الجبل) ثلاثٌ كلَّ يوم… أستاذ، هذه قاعدةُ أمي في الحفظ: قليلٌ دائم!'],['الأستاذ فؤاد','(يبتسم واسعاً) أمُّكَ معلمةٌ فطرية إذن. زدْ عليها قاعدتي: اسألْ عن كلِّ كلمةٍ لا تفهمُها بلا خجل — فالسؤالُ نصفُ العلم، والخجلُ في طلبِ العلمِ خسارةٌ صافية.']],vo:'دفترٌ أخضرُ وثلاثُ قواعد… هذا كلُّ ما أعطاني الأستاذُ فؤاد. وأقسمُ أنه أعطاني به مفاتيحَ حياتي كلِّها: فبهذا الدفترِ قرأتُ ابنَ هشام، وبه خطبتُ يومَ التخرج، وبه… لكن مهلاً، لكلِّ ثمرةٍ موسمُها.'},
{h:'م٤ · داخلي/خارجي — مونتاج معركة اللسان',d:'مونتاج أسابيع بإيقاع متصاعد: الدفتر الأخضر يمتلئ صفحة صفحة (لقطات مقربة لكلمات: «شاهقٌ… أرومةٌ… يمّم»). يقرأ جهرياً على السطح كل مساء والجد يستمع مغمض العينين يصحح المخارج («قل: ضـاد… من حافةِ اللسان!»). يسأل في الصف بلا خجل — أول مرة يضحكون، ثم يعتادون، ثم يسألون هم معه. يلصق أسماء الأشياء على أثاث البيت بالفصحى — الجدة تجد ورقة «المِنضدة» على طاولتها وتضحك حتى تدمع.',dlg:[['الجد','(في جلسة سطح، يصحح تلاوته لبيت شعر) …أعيدوا صياغتَه! يا صلاح الدين: اللغةُ عضلةٌ — والعضلاتُ لا تُبنى بالبكاءِ بل بالتمرين. عضلةُ لسانِكَ اليومَ أقوى من الشهرِ الماضي… أكملْ ولا تلتفت.']]},
{h:'م٥ · داخلي — الصف، لحظة الحصاد الأولى',d:'بعد أربعة أشهر. حصة قراءة: الأستاذ فؤاد يطلب من يقرأ النص الصعب — نص عن حب الأوطان. صلاح الدين يرفع يده. الصف يتربص… ويبدأ: قراءة فصيحة سليمة كاملة، بمخارجَ ضبطها سطحُ الجد، وتنغيمٍ ورثه عن منبر مانشستر. عند آخر سطر — صمت… ثم يبدأ التصفيق من المقاعد الخلفية نفسها التي ضحكت أول يوم.',dlg:[['التلميذ الذي سخر','(يقترب في الاستراحة محرجاً) سامحني على أولِ يوم… لم أتخيلْ أن أحداً يتقدمُ بهذه السرعة. كيف؟!'],['صلاح الدين','(يخرج الدفتر الأخضر من حقيبته ويريه إياه) ثلاثُ كلماتٍ في اليوم… وأربعةُ أشهر. لا سحرَ ولا عبقرية — سلَّمٌ صغيرٌ لا تتوقفُ عن صعودِه. (يبتسم) وأعترفُ: ضحكتُكم أولَ يومٍ كانت وقوداً ممتازاً!'],['الأستاذ فؤاد','(يمر بجانبهما ويربت كتف صلاح الدين، يقول للصف) احفظوا هذا المشهدَ يا شباب: هكذا يُرَدُّ على السخرية… لا بالدموعِ ولا باللكمات — بالدفترِ الأخضر.']],vo:'وهكذا فُتحتْ خزانةُ اللغة. وسترون في الحلقاتِ القادمةِ ماذا وجدتُ خلفَ بابِها… لكن خذوا من حلقةِ اليومِ جوهرتَها: بين أن تُضحِكَ الصفَّ وبين أن تُبكيَهُ إعجاباً… أربعةُ أشهرٍ ودفترٌ أخضر. لا أكثر.'}],
msg:'اللسان عضلة والسؤال نصف العلم: ثلاث كلمات كل يوم بلا انقطاع — وبين سخرية الصف وتصفيقه أربعة أشهر ودفتر أخضر.',apply:'أنشئ «دفتر كنوز اللغة»: كل يوم ٣ كلمات فصيحة جديدة تكتبها وتستعملها في جملة تقولها فعلاً لأهلك.'},

{n:47,t:'حلقةُ الفجرِ عندَ الشيخِ محمود',ic:'📿',age:'١٠ سنوات ونصف',loc:'مسجد الحي — عمّان',corner:'quran',goal:'آداب طالب القرآن مع شيخه: التبكير والاستماع والأدب قبل الحفظ',chars:['صلاح الدين','الجد','الشيخ محمود','أطفال الحلقة'],
scenes:[
{h:'م١ · خارجي — طريق الفجر، عتمة وسكينة',d:'الخامسة فجراً. الجد وحفيده يمشيان في أزقة الحارة النائمة — عصا الجد تنقر الحجر بإيقاع ثابت، وفي يد صلاح الدين ترمس قهوة صغير أعدته الجدة «هدية للشيخ». أذان الفجر يرتفع من ثلاث مآذن متداخلة.',dlg:[['صلاح الدين','(مأخوذاً بتداخل الأذانات) في مانشستر كان فجرُنا صامتاً إلا من منبهي… هنا السماءُ نفسُها توقظُك!'],['الجد','ولهذا أحضرتُكَ بنفسي أولَ يوم. اسمعني قبل أن ندخل: الشيخُ محمود حفَّظَ القرآنَ لنصفِ رجالِ هذه الحارة — أنا أوصلتُ أباكَ لحلقتِهِ قبل ثلاثين سنة، واليومَ أوصلُ ابنَه. لكن اعلمْ: حلقتُهُ لها هيبةٌ وقوانين. تأدَّبْ قبل أن تتعلم… فالأدبُ بابُ العلم.']],vo:'ثلاثةُ أجيالٍ على بابِ رجلٍ واحد… في تلكَ اللحظةِ فهمتُ معنى كلمةٍ كنتُ أسمعُها ولا أعيها: «السند». العلمُ عندنا يا أصدقائي سلسلةٌ من القلوبِ إلى القلوب… تمتدُّ حتى تصلَ رسولَ اللهِ ﷺ نفسَه.'},
{h:'م٢ · داخلي — المسجد، هيبة الدخول الأول',d:'بعد الصلاة. زاوية الحلقة: بساط أخضر، حوامل مصاحف خشبية مصفوفة، وعشرون طفلاً جلوساً كخلية نحل خافتة الطنين — كلٌّ يراجع همساً. في الصدر: الشيخ محمود — سبعيني بعباءة رمادية، عينان تحفظان الوجوه، ومسبحة لا تتوقف. الجد يقدّم حفيده.',dlg:[['الجد','شيخَنا… هذا صلاحُ الدين بنُ أيوب. حفيدي… وثالثُ من أسلمُهُ لكَ من بيتنا.'],['الشيخ محمود','(يرفع عينيه ببطء… يتأمل الفتى من قدميه إلى وجهه) صلاحُ الدين… اسمٌ ثقيل. (للجد) يا أبا أيوب، الاسمُ وحدَهُ لا يكفي — سنرى اللسانَ والقلب. (لصلاح الدين، بحدة مقصودة) قوانينُ حلقتي ثلاثة، احفظْها قبل أن تحفظَ عندي حرفاً: من تأخرَ قرأَ آخرَ الحلقة. ومن قاطعَ زميلَهُ راجعَ وحدَه. والمصحفُ لا يوضعُ على الأرضِ أبداً — تحملُهُ فوقَ صدرِكَ أو على الحامل. مفهوم؟'],['صلاح الدين','(واقفاً باستقامة) مفهومٌ يا شيخي… وأزيدُك: لن أجلسَ إلا حيثُ تأمرُني.'],['الشيخ محمود','(أول ملامح ابتسامة تتسلل رغماً عنه… يخفيها بمسبحته) اجلسْ آخرَ الصف. الصدارةُ عندنا تُكتَسَبُ… لا تُهدى.']]},
{h:'م٣ · داخلي — الحلقة، درس الأدب العملي',d:'مونتاج الحلقة الأولى: صلاح الدين يراقب المنظومة المدهشة — طفل يسمّع والبقية آذان صاغية، من ينتهي يقبّل رأس الشيخ ويجلس، طفل تأخر فوقف عند الباب حتى أُذن له وقرأ أخيراً. طفل صغير وضع مصحفه أرضاً سهواً فالتقطه الشيخ قبل أن يستقر — رفعه وقبّله وقال للحلقة كلمته.',dlg:[['الشيخ محمود','(رافعاً المصحف) يا أبنائي… هذا كلامُ من خلقَ السماواتِ والأرض. ملوكُ الدنيا تُحمَلُ رسائلُهم فوقَ الرؤوس… أفنضعُ رسالةَ ملكِ الملوكِ تحتَ الرُّكَب؟ الأدبُ مع المصحفِ أدبٌ مع صاحبِ الكلام. من عظَّمَ الكتابَ… فتحَ اللهُ قلبَهُ للكتاب.']],vo:'عشرون طفلاً وشيخٌ واحد… ونظامٌ أدقُّ من ساعةِ مطار. لا صراخَ ولا عصا — هيبةُ العلمِ وحدَها تدير المكان. وأدركتُ الفرق: في المدرسةِ يعلمونكَ لتنجح… وفي الحلقةِ يؤدبونكَ لتحمِل.'},
{h:'م٤ · داخلي — الحلقة، اختبار الشيخ',d:'آخر الحلقة. الشيخ يشير لصلاح الدين — دوره: «أسمِعني ما معك». يجلس الفتى أمامه على ركبتيه، ويسمّع سورة الفجر بترتيل مانشستر الهادئ. الشيخ مغمض العينين… ثم يفتحهما فجأة عند الآية الأخيرة.',dlg:[['الشيخ محمود','قفْ عندك. «فادخلي في عبادي وادخلي جنتي»… أخبرني: لمن تُقالُ هذه؟ وما «النفسُ المطمئنة»؟'],['صلاح الدين','(بلا تردد — تدريب أمه القديم) تُقالُ للنفسِ المؤمنةِ عندَ الموتِ ويومَ القيامة: يا أيتها النفسُ المطمئنة — التي آمنتْ فاطمأنتْ بذكرِ الله، ورضيتْ بقضائِه. أمي تقول: هي النفسُ التي تقولُ لربها «رضيتُ» فيقولُ لها «ادخلي». وأنا أسأل يا شيخي… (يتردد ثم يجرؤ) هل سمّيتَ الحلقةَ بالفجرِ لهذا؟ لأن سورةَ الفجرِ فيها أعظمُ بشارة؟'],['الشيخ محمود','(صمت طويل… يلتفت للجد الجالس عند العمود)… يا أبا أيوب. حفيدُكَ يسألُ أسئلةَ من جلسَ في الحلقاتِ عشرَ سنين. (يلتفت للفتى وعيناه تلمعان) من علَّمَكَ أن تفهمَ ما تحفظ؟'],['صلاح الدين','أمي… كانت تحكي لي السورةَ قبل أن أحفظَها.'],['الشيخ محمود','(يهز رأسه ببطء) بارك اللهُ في الأمهات… هنَّ الحلقاتُ الأولى.']]},
{h:'م٥ · داخلي — الحلقة، البشارة',d:'الشيخ يقوم متوكئاً، يمشي إلى صدر الحلقة ويشير إلى البساط الأمامي — صف صغير من خمسة أطفال هم الأكبر حفظاً.',dlg:[['الشيخ محمود','هذا «صفُّ الطامحين»: من عاهدوني على الختمِ الكامل — القرآنُ كلُّهُ في صدورِهم قبلَ الخامسةَ عشرة. شرطُهُ فجرٌ لا ينكسر، وفهمٌ مع الحفظ، وخُلقٌ يليقُ بالحمل. (يلتفت لصلاح الدين) البارحةَ كانوا خمسة… (يشير للمقعد السادس الفارغ) اجلس. من اليومِ أنتَ سادسُهم — يا حاملَ نصفِ جزءِ عمّ، وفاهمَ الفجر.'],['صلاح الدين','(ينتقل للمقعد بخطوات مرتجفة… يجلس، ثم يلتفت لجده عند العمود — الجد يرفع سبابته إلى السماء: الحمد لله)']],vo:'من آخرِ الصفِّ إلى صفِّ الطامحين في حلقةٍ واحدة — ليس لأني الأذكى… بل لأن أمي حكتْ لي القصصَ قبلَ الحفظ، ولأني وقفتُ للشيخِ وقفةَ الأدب. يا طالبَ العلم: الأدبُ يفتحُ لكَ الأبوابَ التي لا يفتحُها الذكاء… احفظْها عني.'}],
msg:'الأدب باب العلم والسند سلسلة القلوب: عظّم المصحف وبكّر واستمع — فالأدب يفتح ما لا يفتحه الذكاء.',apply:'اضبط أدبك مع معلم القرآن: بكّر قبل الموعد، ولا تقاطع، واحمل مصحفك بيمينك ولا تضعه أرضاً أبداً.'},

{n:48,t:'معاذٌ وحمزة',ic:'🤝',age:'١١ سنة',loc:'الحي والمدرسة — عمّان',corner:'social',goal:'اختيار الصاحب: «المرء على دين خليله فلينظر أحدكم من يخالل»',chars:['صلاح الدين','حمزة','معاذ','شلة الشارع','العجوز أبو سليم','الجد'],
scenes:[
{h:'م١ · خارجي — حارة عمّان، خريطة الأصدقاء',d:'مونتاج تعريفي بأسلوب خفيف: الحارة بعد العصر — ثلاثة عوالم. (١) شلة الشارع: سبعة فتيان على الناصية، هواتف وضحك صاخب حتى منتصف الليل ومقالب على المارة — زعيمهم «شادي» صاحب أحدث جوال. (٢) حمزة ابن عمه: قلب ذهب وجسد لا يهدأ واندفاع يسبق عقله. (٣) معاذ: جاره ورفيق الحلقة — هادئ، يمشي وفي جيبه مصحف صغير، يبتسم أكثر مما يتكلم.',dlg:[['شادي','(يعترض طريق صلاح الدين ويلقي ذراعه على كتفه) يا ابنَ لندن! تعالَ اسهرْ معنا — عندنا ألعابٌ على الجوالِ ما وصلتْ حارتَكم الإنجليزية! شلتُنا أحلى شلة… جرِّب.'],['صلاح الدين','(بلباقة مانشستر) مانشستر لا لندن يا شادي — وأشكرُك… عندي حلقةُ فجرٍ لا ترحمُ السهر!']],vo:'حارةٌ جديدةٌ يعني امتحاناً قديماً: من تصاحب؟ وكان جدي يراقبُ صراعَ العوالمِ الثلاثةِ على حفيدِهِ بصمتِ الخبراء… حتى جاءتْ ليلةُ الدرس.'},
{h:'م٢ · خارجي — سطح البيت، حديث الجد',d:'جلسة السطح المسائية. الجد يقشر برتقالة ويقسمها — لكل حبة حكمة.',dlg:[['الجد','رأيتُ شادي يحوّمُ حولك… اسمعْ من عمَّرَ ثمانين: قال رسولُ اللهِ ﷺ: المرءُ على دينِ خليلِه، فلينظرْ أحدُكم من يخالل. والخليلُ يا حبيبي من الخِلال — يعني يدخلُ خلالَ قلبِكَ حيثُ لا يدخلُ أحد… فانظرْ من تُدخِل.'],['صلاح الدين','وكيف أعرفُ الصاحبَ الساحبَ إلى فوق… من الساحبِ إلى تحت؟'],['الجد','(يرفع حبة برتقال) ثلاثُ علامات، خذها ميزاناً: انظرْ ماذا يفعلُ وقتَ الأذان. وانظرْ كيف يعاملُ الضعيفَ الذي لا ينفعُهُ ولا يضرُّه. وانظرْ هل يجرؤ أن يقولَ لكَ «أخطأتَ» في وجهِك. من صدقَ في الثلاث… فأمسِكْ به ولو كان فقيرَ الجيبِ خشنَ الثياب.']]},
{h:'م٣ · خارجي — الحارة، ليلة المقلب الكاشف',d:'ليلة صيف. شلة شادي متحلقة تتآمر ضاحكة: خطة مقلب «مضحك» — طرق باب العجوز أبي سليم (الأرمل الوحيد بطيء الحركة) والاختباء، مرات متتالية، وتصويره وهو يتعثر خارجاً غاضباً «للمشاهدات». يعرضون على صلاح الدين وحمزة ومعاذ المشاركة — «اختبار انضمام».',dlg:[['شادي','(ممسكاً هاتفه جاهزاً للتصوير) دورُكَ يا ابنَ مانشستر: اطرقِ البابَ واهرب! أو… (يبتسم ساخراً) خائف؟'],['صلاح الدين','(ينظر للباب العتيق… ثم يستدير لشادي بصوت الحلقة الهادئ) خائف؟ نعم — لكن ليس منك. خائفٌ من إلهٍ يراني أضحكُ على شيخٍ بعمرِ جدي. هذا ليس مقلباً يا شادي… هذا أذى. وأنا لا أهربُ من الأبواب — أنا أطرقُها وأقف.'],['شادي','(يتجمد هو والشلة — أفسد اللعبة كلها) …خرِّيجُ الحلقاتِ جاءَ يعظُنا! من معه؟!'],['حمزة ومعاذ','(يخطوان في وقت واحد ويقفان بجانبه — ثلاثة في مواجهة سبعة)'],['حمزة','(مندفعاً كعادته لكن في الاتجاه الصحيح) ابنُ عمي معه حق! ومن يطرقْ بابَ أبي سليم للأذى… يمرَّ عليَّ أولاً!'],['معاذ','(بهدوئه القاتل، يلتقط الهاتف بعينيه) واحذفوا ما صورتم قبلَها… فبعضُ المشاهداتِ تُشترى بالنار.']]},
{h:'م٤ · خارجي/داخلي — باب أبي سليم، قلب المشهد',d:'الشلة تنسحب متذمرة. الفتية الثلاثة يقفون أمام باب العجوز — وصلاح الدين يطرقه فعلاً. يفتح أبو سليم متحفزاً (اعتاد المقالب) فيجد ثلاثة فتية يحملون أكياس خضار تركها على عتبته ساعي البقالة.',dlg:[['صلاح الدين','مساءُ الخير عمي… أكياسُكَ على العتبةِ من العصر، حملناها لك. وجئنا نعتذر: بعضُ فتيانِ الحارةِ آذوكَ سابقاً… ونحن نستحي مما فعلوا.'],['أبو سليم','(يتفحصهم بذهول… ثم تغرورق عيناه) منذ ماتتْ أمُّ سليم… ما طرقَ بابي أحدٌ إلا هارباً. ادخلوا… ادخلوا يا أولادي — عندي شايٌ وقصصٌ عن حارتِكم هذه من قبلِ أن تولدَ آباؤكم!'],['الفتية الثلاثة','(يتبادلون نظرة… ويدخلون. من داخل البيت: ضحكات تتصاعد مع حكايات العجوز)']],vo:'دخلنا بيتَ أبي سليم ثلاثةَ غرباء… وخرجنا عصبةً. غريبٌ أمرُ الصداقاتِ الحقيقية: لا تولدُ في الحفلات… تولدُ في المواقف. موقفٌ واحدٌ صادقٌ يغني عن ألفِ سهرة.'},
{h:'م٥ · خارجي — سطح بيت الجد، عهد العصبة',d:'الليلة نفسها. الفتية الثلاثة على السطح تحت النجوم — الجدة أرسلت صينية كنافة «للضيوف الجدد». صلاح الدين يخرج دفتره (دفتر المشاريع من مانشستر) ويفتح صفحة جديدة.',dlg:[['صلاح الدين','في مانشستر تعلمتُ أن الأشياءَ العظيمةَ تُكتَب. (يكتب والاثنان يقرآن) «عهدُ العصبة: نتصاحبُ في اللهِ لا في المصلحة. نتناصحُ في الوجهِ ولا نغتابُ في الظهر. من رأى أخاهُ يميلُ سحبَهُ ولا يفضحُه. ولا نتخاذلُ عن بعضِنا… مهما كبرتِ المواقف». من يوقع؟'],['حمزة','(يخطف القلم ويوقع بحماس) أوقعُ بالدم لو طلبت!'],['معاذ','(يوقع بهدوء ثم يرفع عينيه) بشرطٍ أزيدُه: «ونذكِّرُ بعضَنا بالفجر». فأنا أعرفُكما… (يبتسم) النومُ عدوُّ العهود.'],['صلاح الدين','(يضحك ويضيف الشرط ويوقع) شهدَ اللهُ… ثم النجوم.']],vo:'ثلاثةُ توقيعاتٍ صبيانيةٍ على دفترٍ صغير… تضحكون؟ هذا «العهدُ» ظلَّ يعملُ خمسَ عشرةَ سنة: سيسندُني حمزةُ يومَ أضعف، وسيوقظُني معاذُ لألفِ فجر، وسيقفان معي يوماً في ساحةِ… صبراً — كلُّ شيءٍ بوقتِه. فقط احفظوا الميزان: الصاحبُ ساحب… فاختر من يسحبُكَ إلى فوق.'}],
msg:'المرء على دين خليله: الصداقات الحقيقية تولد في المواقف لا السهرات — فاختر الساحب إلى فوق ووقّع معه عهداً.',apply:'انظر في أصحابك نظرة صادقة: من يسحبك إلى فوق ومن إلى تحت؟ اقترب من الأول اليوم اقتراباً عملياً.'},

{n:49,t:'سوقُ الجمعة',ic:'🧺',age:'١١ سنة',loc:'سوق عمّان الشعبي',corner:'social',goal:'أخلاق السوق المسلم: البيع الصادق والكيل الوافي — «التاجر الصدوق مع النبيين»',chars:['صلاح الدين','الجد','أبو أحمد البائع','بائع غشاش','زبائن'],
scenes:[
{h:'م١ · خارجي — السوق الشعبي، صباح الجمعة',d:'انفجار حسي: جبال بطيخ، أهرامات بهارات ملونة، سمك يلمع على الثلج، منادون يتغنون ببضاعتهم («يا عسل يا بندورة!»)، وروائح كعك بسمسم وقهوة. صلاح الدين يدور برأسه مبهوراً — سوقه الأول. الجد يمشي فيه مشية ملك متقاعد: الكل يسلّم عليه.',dlg:[['صلاح الدين','(وسط الضجيج) جدي! هذا ليس سوقاً… هذا مهرجان!'],['الجد','(يضحك) وأكثر! هذا يا حبيبي أقدمُ مدرسةٍ في الإسلام: هنا كان النبيُّ ﷺ يمشي ويعلّم، وهنا تُختبَرُ الأخلاقُ كلَّ يوم أشدَّ من اختبارِ المساجد — ففي المسجدِ يراكَ الناس… وفي السوقِ يغيبون ويبقى الله. افتحْ عينيكَ اليوم: سأريكَ جنةً ونارَاً على بسطاتٍ متجاورة.']],vo:'جنةٌ ونارٌ على بسطاتٍ متجاورة… ظننتُها مبالغةَ جدٍّ يحبُّ الكلامَ الكبير. بعد ساعةٍ واحدة… كنتُ قد رأيتُ الاثنتين بعينيّ.'},
{h:'م٢ · خارجي — بسطة أبي أحمد، درس الجنة',d:'بسطة خضار متواضعة مكتظة بالزبائن رغم وجود بسطات أكبر. صاحبها أبو أحمد: ستيني بمريول نظيف وميزان لامع. الجد وحفيده يراقبان مشهداً عجيباً: زبونة تختار صندوق فراولة، فيسحبه أبو أحمد من يدها.',dlg:[['أبو أحمد','لا يا حجة، ليس هذا — هذا الصندوقُ أصابَهُ المطرُ البارحةَ من تحت، ونصفُهُ لن يصمدَ ليومين. خذي من هذا الصندوقِ الشمالي… وهو أرخصُ بربعِ دينار.'],['الزبونة','(مندهشة) تدلُّني على عيبِ بضاعتِك وترخصُ لي؟! يا رجل… من ثلاثين سنةً أشتري منكَ ولا أفهمُ كيف لم تفلس!'],['أبو أحمد','(يزن لها ويزيد حبات فوق الميزان) من ثلاثين سنةً تشترين مني… وهذا جوابُ سؤالِك يا حجة! قال ﷺ: البيِّعانِ بالخيارِ ما لم يتفرقا، فإن صدقا وبيَّنا بوركَ لهما في بيعِهما. الدينارُ الذي يذهبُ بالصدقِ… يعودُ بالبركةِ عشرة.'],['الجد','(هامساً لحفيده) احفظِ المشهد: خسرَ ربعَ دينارٍ أمامَك… وربحَ ثلاثين سنةً من الأرزاق. هذه هي «الجنة» التي وعدتُك — التاجرُ الصدوقُ الأمينُ مع النبيين والصدِّيقين والشهداء… يومَ القيامةِ يُحشَرُ معهم.']]},
{h:'م٣ · خارجي — الطرف الآخر من السوق، درس النار',d:'بسطة كبيرة صاخبة — صاحبها ينادي بأعلى صوت: «أحلى بندورة! من تحت الشجرة!». لكن صلاح الدين يلحظ ما علّمه الجد ملاحظته: البائع يعرض الحبات الحمراء فوقاً ويغرف للزبائن من صندوق خلفي مختلف، وإبهامه يستقر على كفة الميزان مع كل وزنة. الزبائن قلة، ونظراتهم حذرة، وامرأة تفتح كيسها بعيداً وتكتشف الحبات المعفنة فتعود غاضبة.',dlg:[['صلاح الدين','(هامساً) جدي… رأيتُ إبهامَه! يسرقُ بالميزانِ نفسِه!'],['الجد','(بحزن لا بشماتة) ويلٌ للمطففين… الذين إذا اكتالوا على الناسِ يستوفون وإذا كالوهم أو وزنوهم يُخسرون. سورةٌ كاملةٌ نزلتْ في إبهامٍ مثلِ هذا. انظرْ حولَه: بضاعتُهُ أكثرُ من أبي أحمد وسعرُهُ أرخص… فلماذا بسطتُهُ خاوية؟ لأن الغشاشَ يكسبُ الصفقةَ الأولى… ويخسرُ كلَّ ما بعدَها. الناسُ يا حبيبي موازينُ تمشي — يزنون التجارَ بأدقَّ من موازينِهم.']],vo:'بسطتان في سوقٍ واحد… واحدةٌ يحرسُها الصدقُ وتفيضُ رزقاً، وأخرى يأكلُها إبهامٌ خائن. ومن يومِها أرى الأسواقَ كما علمني جدي: امتحاناتٍ مفتوحةً… يصححُها اللهُ بالبركة.'},
{h:'م٤ · خارجي — بسطة أبي أحمد، تجربة البيع الأولى',d:'الجد يطلب من صديقه القديم طلباً غريباً: «شغِّلِ الولدَ عندكَ ساعة — بلا أجر، الأجرُ هو الدرس». أبو أحمد يقبل ضاحكاً ويلبس الفتى مريولاً يسبح فيه. مونتاج ساعة العمل: يتعلم ترتيب الحبات «الوجه مثل القلب — لا تجمّل وجهاً وتخبئ عيباً»، ينادي على البضاعة بخجل ثم بحماس، يزن ويتعلم إراحة الكفة «زِدْ حبةً ولا تنقصْ حبة».',dlg:[['أبو أحمد','(يراقبه يزن لزبون) أحسنت… لكن انتبهْ للقاعدةِ الذهبية: إذا شككتَ في الوزن… فالميلُ لصالحِ الزبونِ دائماً. نحن لا نبيعُ خضاراً يا صلاح الدين… نحن نبيعُ ثقة. الخضارُ تفنى في يومين — والثقةُ تبقى ثلاثين سنة.']]},
{h:'م٥ · خارجي — البسطة، امتحان الزيادة',d:'آخر الساعة: زبون مستعجل يدفع ويمضي. صلاح الدين يعدّ النقود فيكتشف: دفع ديناراً زيادة. يلتفت — الزبون غاب في الزحام. لقطة قريبة: الدينار في كفه… أبو أحمد والجد منشغلان ولم يريا شيئاً. يقفز الفتى من خلف البسطة ويشق الزحام ركضاً.',dlg:[['صلاح الدين','(يلحق الزبون لاهثاً بعد مئة متر) عمي! عمي انتظر! …دفعتَ ديناراً زيادة!'],['الزبون','(يتفحص الدينار مذهولاً) ركضتَ خلفي كلَّ هذا… لأجلِ دينار؟ ابنُ من أنتَ يا بطل؟'],['صلاح الدين','(يلتقط أنفاسه ويبتسم) ابنُ بسطةِ أبي أحمد… ونحن هناك لا نبيعُ خضاراً — نبيعُ ثقة!'],['الجد','(وصل يتوكأ عصاه شاهداً على المشهد… يضع يده على قلبه ويهمس) الرزقُ لا ينقصُهُ الصدقُ يا ولدي… والآن — الآن أشهدُ أنكَ تعلمتَ درسَ السوق.']],vo:'دينارٌ واحدٌ ركضتُ خلفَهُ مئةَ متر… وما زلتُ أركضُ خلفَ أمثالِهِ إلى اليوم — في صفقاتٍ صارتْ بملايينِ الدنانير. المبلغُ يتغير… والقاعدةُ لا تتغير: نحن لا نبيعُ بضائع. نحن نبيعُ ثقة.'}],
msg:'التاجر الصدوق مع النبيين: بيّن العيب وأرجح الميزان ورُدّ الزيادة — فالغشاش يكسب صفقة ويخسر البركة كلها.',apply:'إن اشتريت اليوم وأعطاك البائع زيادة سهواً فأرجعها فوراً — وراقب بائعاً صادقاً وتعلم منه حركة واحدة.'},

{n:50,t:'من هنا أرى فلسطين',ic:'⛰️',age:'١١ سنة',loc:'جبل نيبو — الأردن',corner:'quds',goal:'اللقاء البصري الأول بالأرض المقدسة: من الصورة على الجدار إلى الأفق الحقيقي',chars:['العائلة','الجد','الجدة'],
scenes:[
{h:'م١ · خارجي — الطريق الجبلي، صباح رحلة',d:'سيارة العائلة تلتف في طريق جبلي. أناشيد جماعية، الجدة توزع سندويشات الزعتر، يوسف يعد الأغنام في التلال. لكن الكاميرا تلتقط ما لا يلتقطه الأطفال: الجد صامت غير عادته، يمسك عصاه بقبضة مشدودة، وعيناه معلقتان بالأفق الغربي. مريم تلحظ وتتبادل نظرة مع أيوب.',dlg:[['يوسف','جدي! لماذا لا تغني معنا؟ أنتَ صاحبُ أحلى صوت!'],['الجد','(يبتسم بنصف قلب) أدَّخرُ صوتي يا حبيبي… فوقَ الجبلِ سنحتاجُهُ لشيءٍ أهمَّ من الغناء.']],vo:'كان جدي قد رتَّبَ هذه الرحلةَ منذ أسابيع، ورفضَ أن يخبرَنا وجهتَها. قال فقط جملةً واحدة: «سآخذُكم إلى المكانِ الذي أطلُّ منه على قلبي». لم أفهمْها يومَها… وسأفهمُها بعدَ ساعة، فهماً سيغيرُ عمري كلَّه.'},
{h:'م٢ · خارجي — قمة جبل نيبو، لحظة الحافة',d:'القمة: ريح عالية، وأفق مفتوح بلا نهاية. الجد يمشي بهم إلى الحافة الغربية — تحتهم يمتد وادي الأردن، والبحر الميت يلمع كمرآة زرقاء، وخلفه… تلال باهتة تلوح في الضباب الذهبي. الجد يقف صامتاً دقيقة كاملة (زمن حقيقي — الريح وحدها تتكلم)… ثم يرفع عصاه ببطء نحو الأفق.',dlg:[['الجد','(بصوت عميق تحمله الريح) انظروا حيثُ تشيرُ العصا… تلكَ الأرضُ التي تلمعُ خلفَ الغور — تلكَ فلسطين. (يحرك العصا شمالاً قليلاً) وخلفَ ذلك الجبلِ الأزرقِ البعيد… أريحا. وبعدَها بثلاثين ميلاً فقط… (صوته ينكسر للمرة الأولى في السلسلة)… القدس. مدينتي.'],['صلاح الدين','(يتقدم خطوة نحو الحافة، عيناه تتسعان… يهمس) هذه… هذه هي؟ بهذا القرب؟! (يلتفت لجده بصدمة حقيقية) جدي — أنا أراها! كلُّ هذا القرب؟!']],vo:'إحدى عشرةَ سنةً وأنا أعرفُ فلسطينَ صورةً على جدار، ودعاءً في قنوت، وقصةً قبلَ النوم. وفي تلكَ اللحظة… صارتْ أرضاً حقيقيةً تلمعُ تحتَ شمسِ الظهيرة، على مدِّ البصر. لا شيءَ يهزُّكَ مثلَ اكتشافِ أن حلمَكَ… له عنوانٌ يُرى بالعين.'},
{h:'م٣ · خارجي — القمة، السؤال الصاعق',d:'صلاح الدين يحدق في الأفق، وعقله يعمل بمنطق الطفل القاتل في بساطته.',dlg:[['صلاح الدين','جدي… سؤال. الطائرةُ حملتْنا من مانشستر ستَّ ساعاتٍ فوقَ بحارٍ وجبال. وهذه… (يشير) هذه أقربُ من مشوارِ مدرستي! إن كانت بهذا القرب… فلماذا لا نذهب؟ الآن! نركبُ السيارةَ وننزلُ الوادي و…'],['الكبار','(صمت ثقيل — أيوب ينظر لحذائه، مريم تضم شام، الجدة تمسح عينيها بطرف منديلها)'],['الجد','(يجثو على ركبته المتعبة ليصير بمستوى عيني حفيده) لأن بيني وبينها يا حبيبي… أقسى أنواعِ البعد: بابٌ مغلقٌ بالظلم. القريبُ المحرومُ يا صلاح الدين… أشدُّ وجعاً من البعيدِ الناسي. أنا أطلُّ عليها من هذا الجبلِ منذ خمسين سنة — أراها ولا أصلُها.'],['صلاح الدين','(بعينين تغرورقان — غضب طفل من ظلم لا يفهم منطقه) هذا… هذا ليس عدلاً! من أغلقَ البابَ؟ ولماذا لا يفتحُهُ أحد؟!']]},
{h:'م٤ · خارجي — القمة، انتقال المفتاح',d:'المشهد المحوري للسلسلة كلها. الجد ينهض ببطء… يمد يده إلى صدره ويخرج المفتاح الحديدي من تحت ثوبه — يلمع في شمس الجبل لأول مرة خارج البيت. يرفعه أمام الأفق لحظة… ثم يضعه في كف حفيده الصغيرة ويطبق أصابعه عليه.',dlg:[['الجد','امسكْه… للمرةِ الأولى بيدِك، وأنتَ ترى بعينِكَ البلادَ التي يخصُّها. (يشد قبضة الحفيد على الحديد) اسمعني يا صلاحَ الدين، فأنا لن أكررَ هذا الكلام: الأبوابُ المغلقةُ بالظلم… لا تبقى مغلقةً إلى الأبد. هذا وعدُ اللهِ قبلَ أن يكونَ أملَ العجائز. لكنها لا تُفتَحُ بالبكاءِ ولا بالخطبِ ولا بالغضبِ وحدَه… تُفتَحُ حينَ يوجدُ جيلٌ يحملُ المفتاحَ وقلبُهُ نظيف: نظيفٌ من الكذبِ والخيانةِ والفرقة — عامرٌ بالعلمِ والقوةِ والرحمة. أتفهمُني؟'],['صلاح الدين','(يشعر بثقل الحديد البارد في كفه… يرفع المفتاح نحو الأفق بذراع ممدودة — لقطة أيقونية: طفل على قمة جبل، يرفع مفتاحاً بين عينيه وبين القدس البعيدة) أفهمُك… وأعدُكَ يا جدي: سأحملُهُ… وسأنظِّفُ قلبي كلَّ يوم. حتى تُفتَحَ الأبواب.']],vo:'لم يقلْ جدي «سأعطيكَ المفتاح» — أعادَهُ إلى صدرِهِ بعدَ دقيقة. كان أذكى من ذلك: يعرفُ أن الأماناتِ لا تُعطى في لحظةِ حماس… تُعطى حين ينضجُ حاملُها. لكنه في تلك الدقيقةِ زرعَ في كفي بصمةَ حديدٍ… ما زلتُ أشعرُ بها كلما أغلقتُ قبضتي.'},
{h:'م٥ · خارجي — القمة، لقطة العائلة الأخيرة',d:'الغروب يقترب. العائلة تصطف عند الحافة لصورة تذكارية — الجد في الوسط رافعاً عصاه نحو الغرب، والجميع ينظرون حيث تشير (لا إلى الكاميرا). أيوب يثبت الهاتف على صخرة ويشغل المؤقت. اللقطة تتجمد وتتحول إلى صورة فوتوغرافية بإطار — ستظهر هذه الصورة معلقةً في كل بيوت صلاح الدين القادمة حتى آخر حلقة.',dlg:[['الجدة خديجة','(وهي تنزل من الجبل ممسكة ذراع زوجها، تغني موالاً قديماً بصوت خفيض) «يا جبلُ ما يهزَّكَ ريح…»'],['صلاح الدين','(يمشي خلفهم، يلتفت للأفق التفاتة أخيرة… ويهمس) انتظريني.']],vo:'نزلنا من جبلِ نيبو ولم نعدْ كما صعدنا — أنا على الأقل. صعدتُ طفلاً يحفظُ قضيةً… ونزلتُ فتىً رآها. ومن يومِها أفهمُ لماذا أخذَنا جدي إلى هناك: بعضُ الدروسِ لا تُحكى يا أصدقائي… تُشاهَدُ من قمةِ جبل.'}],
msg:'القريب المحروم أشد وجعاً من البعيد: الأبواب المغلقة بالظلم لا تبقى مغلقة — لكنها تُفتح بجيلٍ يحمل المفتاح وقلبه نظيف.',apply:'افتح الخريطة وابحث: كم تبعد القدس عن بلدك؟ اكتب الرقم وعلّقه عند سريرك — القرب يصنع الهمة.'},

{n:51,t:'ميدانُ الفرسان',ic:'🏇',age:'١١ سنة ونصف',loc:'نادي الفروسية والرماية',corner:'sport',goal:'الرياضات السنية الثلاث: الرماية والسباحة وركوب الخيل — إعداد لا استعراض',chars:['صلاح الدين','أيوب','المدرب أبو فارس','المهرة ريح'],
scenes:[
{h:'م١ · خارجي — نادي الفروسية، الدهشة الأولى',d:'مكافأة التفوق في العربية: أيوب يدخل بابنه بوابة نادٍ على أطراف عمّان — اصطبلات حجرية، مضمار ترابي يتصاعد غباره خلف خيول تتسابق، وميدان رماية تصطف فيه أهداف ملونة. صلاح الدين متسمر: فتيان بعمره يمتطون خيولاً حقيقية.',dlg:[['صلاح الدين','هذا المكانُ من كتبِ التاريخ! بابا… أنا سأتعلمُ هذا كلَّه؟'],['أيوب','هديةُ الدفترِ الأخضر! لكن اعلمْ لماذا اخترنا هذا بالذات: عمرُ بنُ الخطاب أوصى: علِّموا أولادَكم السباحةَ والرمايةَ وركوبَ الخيل. السباحةَ أتقنتَها في مانشستر… واليومَ نكملُ وصيةَ عمر. هذه ليست هواياتٍ يا صلاح الدين — هذا إعدادٌ. المسلمُ القويُّ مشروعٌ متكاملٌ: عقلٌ يفهم، وقلبٌ يخشع… وجسدٌ يحمِلُ الاثنين.'],['المدرب أبو فارس','(يقترب — خمسيني مفتول الساعدين بصوت رعد ودفء معاً) أهلاً بالفارسِ الجديد! القاعدةُ الأولى عندي: الميدانُ يبدأ بالتواضع — من دخلَهُ متكبراً… علَّمتْهُ الخيلُ الأدبَ بطريقتِها!']],vo:'«علَّمتْهُ الخيلُ الأدبَ بطريقتِها»… ضحكتُ من العبارة. بعد ساعتين… كنتُ أنفضُ ترابَ المضمارِ عن ثيابي للمرةِ الثانية، وأفهمُها فهماً عملياً جداً.'},
{h:'م٢ · خارجي — الاصطبل، لقاء ريح',d:'أبو فارس يقدمه لمهرة كستنائية بعرف أسود وعينين ذكيتين: «ريح — أجمل خيل النادي وأصعبها مراساً». صلاح الدين يقترب بثقة سباح بطل… فتشب المهرة وتبتعد. يحاول الامتطاء بمساعدة المدرب — تمشي خطوتين ثم تنحني فجأة فيتدحرج فوق رأسها. المرة الثانية: تدور دورة سريعة فيسقط جانباً. ضحكات فتيان الميدان.',dlg:[['صلاح الدين','(ينفض التراب غاضباً) هي تكرهُني! أعطني حصاناً غيرَها!'],['أبو فارس','(يقف بجانبه بهدوء ويراقب ريح) تكرهُك؟ لا يا بطل… هي تقرؤك. الخيلُ يا صلاح الدين مرايا: تشعرُ بقلبِ فارسِها قبل أن يلمسَ سرجَها. أنتَ صعدتَ عليها غاضباً مستعجلاً تريدُ أن «تنتصرَ» عليها… فأرتْكَ رأيَها في الغضب. الكائنُ الحيُّ لا يُقادُ بالقوة… يُقادُ بالثقة. غداً تعودُ — لكن أولَ ساعةٍ ممنوعٌ أن تركبَها: ستمشي بجانبِها فقط… وتحدِّثُها.'],['صلاح الدين','أحدِّثُ… حصاناً؟'],['أبو فارس','(يبتسم) جرِّبْ. وستدهشُك النتيجة.']]},
{h:'م٣ · خارجي — المضمار، مونتاج الترويض المتبادل',d:'مونتاج أسبوعين ساحر: يمشي بجانب ريح صامتاً محرجاً… ثم يبدأ الحديث («اسمعي… أنا أيضاً جديدٌ هنا. تكسّرتْ لغتي في المدرسة كما أسقطتِني أنتِ»). يطعمها تفاحاً من كفه — أول مرة تأكل وأذناها مرتاحتان. يمشطها ويكتشف أن كتفها الأيسر حساس. اليوم العاشر: يمتطيها بهدوء تام — «بسم الله يا ريح… على مهلِك» — فتمشي. تمشي! ثم تخب خبباً خفيفاً والفتى فوقها يضحك من قلبه.',dlg:[['أبو فارس','(يراقب من السياج ويهز رأسه) رأيتَ؟ ما تغيرتِ الفرس… تغيرَ الفارس. اهدأ تهدأ، اصدُقْ تصدُقْك. وهذه يا بطل قاعدةُ القيادةِ كلِّها — من قادَ حصاناً بالثقة… عرفَ كيف تُقادُ القلوب.']],vo:'علمتني ريح ما لم يعلمْني المسبح: الماءُ تقهرُهُ بالتكرار… أما الكائنُ الحيُّ فلا يُقهَر — يُكسَبُ. وسنينَ بعدَها، كلما وقفتُ أمامَ فريقٍ غاضبٍ أو قلبٍ نافر، سمعتُ صوتَ أبي فارس: اهدأ تهدأ… اصدُقْ تصدُقْك.'},
{h:'م٤ · خارجي — ميدان الرماية، قانون السهم',d:'ركن الرماية: قوس تدريبي بحجم الفتيان، وهدف على ثلاثين خطوة. أبو فارس يعلمه الوقفة والتنفس. الرميات الأولى كارثية: فوق الهدف، تحته، وواحدة أصابت هدف الجار (اعتذار محرج). أربعون رمية خاطئة والعناد يتصاعد.',dlg:[['أبو فارس','(يوقفه ويضع يده على صدره) توقف. أخبرني: فيمَ تفكرُ لحظةَ الإفلات؟'],['صلاح الدين','في… في ألا أخطئَ مثلَ الرميةِ السابقة!'],['أبو فارس','ها هو الخلل! عينُكَ على الخطأِ الماضي فيذهبُ السهمُ إليه. القاعدة: السهمُ يذهبُ حيثُ يذهبُ قلبُك — لا حيثُ تنظرُ عينُك. أفرغْ صدرَك: خذ نفساً… سمِّ اللهَ… انسَ الأربعين الخاطئة… ولا يكنْ في كونِكَ كلِّهِ إلا أنتَ والهدف. ثم أفلِتْ كأنكَ لا تفلت.'],['صلاح الدين','(يغمض عينيه لحظة… يتنفس… «بسم الله»… يفتح عينيه على الهدف وحده — ويفلت. السهم يشق الهواء… ويستقر في الحلقة الثانية من المركز. صمت… ثم يقفز الفتى صارخاً والميدان يصفق)'],['أبو فارس','(يضحك رعداً) الحادية والأربعون! هكذا يا ابنَ الأكرمين — أربعون تبني… وواحدةٌ تصيب!']]},
{h:'م٥ · خارجي — النادي، لقطة الفارس المكتمل',d:'مونتاج ختامي بإيقاع ملحمي هادئ: الفجر — يسبح في مسبح النادي (طولات منتظمة). العصر — رمايات تقترب من المركز رمية بعد رمية. الجمعة — يخب على ريح في المضمار والريح في وجهه. لقطة أخيرة: يقف بين الحصان والقوس والمسبح خلفه، يشرب ماء ويلتفت للكاميرا الافتراضية.',dlg:[['أيوب','(جاء يقلّه، يراقب من السياج بجانب أبي فارس) كيف تراه؟'],['أبو فارس','(يتأمل الفتى) أرى كثيرين يأتون ليتعلموا «مهارات»… وقليلين يأتون يبنون أنفسَهم لشيءٍ ما. ابنُكَ من القليل. سألتُهُ مرةً: لماذا تتعبُ هذا التعب؟ فأجابني جواباً ما سمعتُهُ من فتى: قال — لأن عندي موعداً مع أبوابٍ ثقيلة… وأريدُ ذراعين تليقان بفتحِها.']],vo:'سباحةٌ ورمايةٌ وركوبُ خيل… وصيةُ عمرَ تمشي في جسدي. لم أكن أعرفُ متى سأحتاجُها ولا كيف — كنتُ فقط أثقُ بقاعدةِ هذه المرحلةِ كلِّها: أنتَ لا تعرفُ متى يأتي دورُك… لكنكَ تملكُ أن تكونَ جاهزاً حين يأتي.'}],
msg:'علّموا أولادكم السباحة والرماية وركوب الخيل: الكائن الحي يُكسب بالثقة لا يُقهر بالقوة — والسهم يذهب حيث يذهب قلبك.',apply:'جرّب رياضة سنية هذا الشهر (سباحة أو رماية آمنة أو ركوب خيل) — وإن تعذر فثلاث حصص رياضة أسبوعياً بنية الإعداد.'},

{n:52,t:'دموعُ الجدِّ يومَ الختم',ic:'🎉',age:'١٢ سنة',loc:'مسجد الحي — عمّان',corner:'quran',goal:'ختم جزأي عم وتبارك علناً: ثمرة السنوات تُقطف لتزرع همماً جديدة',chars:['صلاح الدين','العائلة','الشيخ محمود','الشيخ إدريس وتوم (عبر الشاشة)'],
scenes:[
{h:'م١ · داخلي — بيت الجد، ليلة الأرق الجميل',d:'الحادية عشرة ليلاً. غداً حفل الحلقة السنوي وتسميعه العلني لجزأي عم وتبارك كاملين. صلاح الدين في فراشه يقلّب — يسمّع لنفسه في العتمة ويتلخبط في «سأل سائل». يتسلل إلى المطبخ فيجد أمه مستيقظة تعد كعك الحفل.',dlg:[['مريم','(دون أن تلتفت — أمومة تعرف الخطى) «سأل سائل» أوقفتْك؟'],['صلاح الدين','(مذهولاً) كيف عرفتِ؟!'],['مريم','لأنها أوقفتْكَ الأسبوعَ كلَّه. (تمسح يديها وتجلس) اسمع سرَّ ليلةِ التسميع: لن أراجعَ معكَ حرفاً الليلة — الحفظُ الذي بنيتَهُ ألفَ فجرٍ لن يهربَ في ليلة. الذي يهربُ هو السكينة… وهذه نستعيدُها بغيرِ المراجعة. توضأ وصلِّ ركعتين، وقل: اللهم إني حفظتُ لوجهِك… فثبِّتْ ما حفظت. ثم نمْ يا حبيبي — غداً لا تحملُ أنتَ القرآن… القرآنُ يحملُك.']],vo:'«القرآنُ يحملُك»… نمتُ على الجملةِ وما فهمتُها. وفي الغد، أمامَ ثلاثمئةِ وجه، حين سيرتجفُ كلُّ شيءٍ فيَّ إلا صوتي… سأفهمُها.'},
{h:'م٢ · داخلي — المسجد، أجواء الحفل',d:'المسجد بأبهى حلة: زينة خضراء، صف كراسي للأهالي، لافتة «حفل حلقة الفجر السنوي». الحضور: أيوب ومريم ويوسف (يحمل لافتة رسمها: «أخي بطل!») وشام على حجر الجدة، والجد في الصدر بكوفية العيد. مفاجأة تقنية: حمزة يثبت هاتفاً على حامل — على الشاشة وجها الشيخ إدريس وتوم من مسجد النور مانشستر!',dlg:[['الشيخ إدريس','(من الشاشة، بصوته العميق) أسمعُكم يا أهلَ عمّان! جئنا نشهدُ ثمرةَ غرسِنا الإنجليزي في أرضِكم الطيبة!'],['توم','(ملوحاً بحماس) صلاح الدين! صديقي! أنا لا أفهمُ ما ستقرأ… لكني أعرفُ أنه عظيم — اقرأ باسمي أيضاً!'],['الجد','(يتأمل الشاشة مندهشاً ثم يضحك) سبحانَ الله… زمانٌ صارت فيه مانشستر جارتَنا في المسجد!']]},
{h:'م٣ · داخلي — المسجد، التسميع',d:'اسمه يُنادى. يجلس أمام الشيخ محمود والميكروفون. البسملة… وينطلق: النبأ، النازعات… صوته يثبت ويعلو. الكاميرا تتنقل: أمه تتابع بشفتيها كل حرف معه، أبوه مغمض العينين، يوسف يرفع لافتته كل سورتين. عند سورة الملك — تتهدج نبرة الفتى في «الذي خلقَ الموتَ والحياةَ ليبلوَكم أيُّكم أحسنُ عملاً»… فيلتقطها المسجد ويردد خلفه همهمة خاشعة. لقطة الذروة: وصوله لآخر آية في تبارك — يرفع صوته بها والمسجد كله معه.',dlg:[['الشيخ محمود','(بعد الحرف الأخير… صمت مهيب ثم) أحسنتَ وأتقنت — ما فتحنا عليكَ حرفاً واحداً. اللهم كما جمَّلتَ صدرَهُ بكلامِك… جمِّلْ به حياتَه.'],['المسجد','(تكبير يهز الجدران — وزغرودة الجدة خديجة تخترق قسم الرجال فيضحك الجميع)']],vo:'جزءان كاملان بلا فتحةٍ واحدة… وأنا أكادُ لا أذكرُ من التسميعِ شيئاً! كان صدقُ أمي معجزةً تمشي: ما حملتُ القرآنَ تلك الليلة… حملني. صوتٌ يخرجُ مني وليس مني، وسكينةٌ ما عرفتُ مثلَها. من ذاقَ تلك اللحظةَ يا أصدقائي… عرفَ لماذا يتعبُ الحفاظُ ألفَ فجر.'},
{h:'م٤ · داخلي — المسجد، انعكاس الأدوار',d:'المشهد الذي بُنيت له الحلقة: الشيخ محمود يعلن «تكريم العائلات — فوراء كل حافظ بيتٌ صابر». يستدعي الوالدين… وفجأة، قبل أن يتحركا — الجد عبد القادر ينهض من الصدر متوكئاً عصاه، يمشي عبر المسجد الصامت نحو حفيده… ويفعل ما قلب المشهد التربوي المعهود: ينحني على رأس الحفيد ويقبّله — الجد يقبل رأس الحفيد.',dlg:[['الجد','(رافعاً رأسه والدموع — التي لم يرها أحد قط — تنساب على وجهه المحفور أمام الجميع) لا تستغربوا يا جماعة… أنا ما قبَّلتُ رأسَ ولد. هذه ليست قبلةً لولد — هذه قبلةٌ لرأسٍ يسكنُهُ ثلثُ القرآن. أبي علَّمَني: يُقبَّلُ الرأسُ الذي شابَ في الطاعة… ورأسٌ حملَ كلامَ اللهِ في الثانيةَ عشرة — شابَ قبلَ شيبِه! (يلتفت للحضور بصوت يرتجف) أنا خرجتُ من القدسِ طفلاً بمفتاحٍ في جيبي… وأشهدُكم اليومَ أني أرى بعيني هاتين… أن الذي سيدخلُها يكبرُ أمامي.'],['المسجد','(يضج بالبكاء والتكبير — حتى عبر الشاشة: الشيخ إدريس يمسح عينيه، وتوم يصفق واقفاً لا يفهم الكلمات ويفهم كل شيء)']]},
{h:'م٥ · داخلي — المسجد، إعلان الطريق القادم',d:'الشيخ محمود يهدئ القاعة ويرفع يده معلناً.',dlg:[['الشيخ محمود','وحتى لا تظنَّ العائلةُ الكريمةُ أن الرحلةَ انتهت… (يبتسم لصلاح الدين) يا صلاحَ الدين: جزآنِ في صدرِك… بقيَ ثمانيةٌ وعشرون. أعلنُها من هذا المنبر: موعدُنا مع ختمِ كتابِ اللهِ كاملاً — قبلَ أن تتمَّ الخامسةَ عشرة. أتقبلُ التحدي؟'],['صلاح الدين','(ينظر لأمه… لأبيه… لجده الذي ما زالت عيناه حمراوين… ثم يقف ويمسك الميكروفون) يا شيخي… أقبلُهُ بشرط: (يلتفت لصف الطامحين) أن نختمَهُ جميعاً — الصفُّ كلُّه. فالجبلُ يُصعَدُ مع الرفاق أجمل!'],['الشيخ محمود','(يضرب كفاً بكف ضاحكاً) اللهُ أكبر! سمعتم يا طامحون؟ قائدُكم رفعَ السقف — الختمُ جماعة! هكذا تكونُ الهمم!']],vo:'وهكذا خرجنا من حفلِ الجزأين بعهدِ الثلاثين. لكن الذي حفظتُهُ من ذلك اليومِ ليس العهد… بل دموعُ رجلٍ ثمانينيٍّ ما بكى في المجاعةِ ولا في الخروجِ ولا على قبورِ أحبتِه — وبكى لثلثِ قرآنٍ في صدرِ حفيدِه. يا حفظةَ القرآنِ الصغار: أنتم لا تحفظون سوراً… أنتم تجبرون قلوبَ أجيالٍ كاملةٍ خلفَكم.'}],
msg:'القرآن يحملك يوم تحمله: خلف كل حافظ بيت صابر وألف فجر — ودموع الأجداد على حفظ الأحفاد أغلى الجوائز.',apply:'حدد «ختمتك الصغيرة» القادمة (سورة أو جزءاً) واكتب تاريخاً مستهدفاً — وادعُ من تحب لحضور تسميعك.'},

{n:53,t:'اثنينِ وخميس',ic:'🌤️',age:'١٢ سنة',loc:'عمّان — صيف',corner:'ibada',goal:'صيام التطوع عادة الأقوياء: تُرفع الأعمال وأنا صائم',chars:['صلاح الدين','معاذ','حمزة','الشيخ محمود','الجدة'],
scenes:[
{h:'م١ · داخلي — الحلقة، عرض التحدي',d:'آخر أيام المدرسة. الشيخ محمود يختم حلقة الفجر بإعلان غير معتاد — يرفع ورقة صفراء.',dlg:[['الشيخ محمود','الصيفُ على الأبواب يا فتيان… شهران بلا مدرسة. والفراغُ لمن لا يملؤهُ بالخير… يملؤهُ غيرُ الخيرِ عنه. فمن رجالُ تحدي الصيف؟ (يقرأ من الورقة) صيامُ الاثنينِ والخميسِ شهراً كاملاً — ثمانيةُ أيام. قال ﷺ: تُعرَضُ الأعمالُ يومَ الاثنينِ والخميس، فأحبُّ أن يُعرَضَ عملي وأنا صائم. تخيلوا يا أبنائي: ملفُّكَ يصعدُ إلى اللهِ… وأنتَ صائم! أيُّ توقيعٍ أجملُ من هذا على الملف؟'],['حمزة','(يرفع يده قبل عقله كعادته) أنا أول! …ثم يهمس لصلاح الدين: الاثنين والخميس فيهما مبارياتُ الحارة، صحيح؟'],['صلاح الدين','(يبتسم ويرفع يده) ولهذا سنشترك… البطولةُ الحقيقيةُ أن تلعبَ وأنتَ صائم. معاذ؟'],['معاذ','(يرفع يده بهدوء) شرطي القديم: أوقظُكما للسحور… فأنا أعرفُكما.']],vo:'ثلاثةُ توقيعاتٍ جديدةٍ على تحدٍّ جديد. لكنَّ صيامَ التطوعِ في تموز… غيرُ كلامِ التطوعِ في الحلقة. وكان في انتظارِنا يومٌ سيفرزُ الكلامَ من الصيام.'},
{h:'م٢ · داخلي — بيت الجد، سحور الفتيان الأول',d:'الثالثة فجراً، أول اثنين. مشهد عائلي فريد: الجدة خديجة أصرت على استضافة «سحور العصبة» — معاذ وحمزة ناما عندهم. طاولة سحور كاملة: لبن وزعتر وبيض وتمر، والجدة تشرف كقائدة مطبخ ميداني.',dlg:[['الجدة','(تضع أمام كل واحد كوب لبن) اشربوا اللبنَ حتى آخرِ قطرة — سلاحُ العطشِ الأول! وكلوا تمراتٍ وتراً… هكذا كان أهلُ القدسِ يتسحرون أيامَ زمان.'],['حمزة','(بفم مليء) تيتا… أنتِ متأكدةٌ أنه لا يوجدُ رمضانُ سريٌّ لا نعرفُهُ نحن؟'],['الجد','(يدخل متوضئاً للفجر، يضحك) هذا يا حبيبي «رمضانُ الأقوياء» — التطوع: لا أحدَ يأمرُك، ولا الناسُ كلُّهم معك، ولا مدافعُ إفطار… أنتَ وربُّكَ فقط. ولهذا أجرُهُ من نوعٍ خاص.'],['صلاح الدين','(يرفع كوبه) نياتٌ خالصة يا شباب: نويتُ صيامَ غدٍ تطوعاً لله. يومَ يُعرَضُ الملفُّ… أريدُ التوقيع!']]},
{h:'م٣ · خارجي — ملعب الحارة، يوم المباراة الحارقة',d:'خميس، الثالثة عصراً، حرارة تموز تلهب الملعب الترابي. مباراة الحارة الكبرى ضد حارة المالحة — والعصبة الثلاثية صائمة. الشوط الأول: أداء طبيعي. الشوط الثاني: الشمس تشتد — لقطات معبرة: حمزة يبلل رأسه من صنبور الملعب (بلا شرب — يفتح فمه تحت الماء ثم يغلقه ويبعده بإرادة مرئية)، شفاه جافة، لاعبو الخصم يشربون أمامهم باستعراض.',dlg:[['لاعب من الخصم','(يشرب ببطء استفزازي) آآآه ما أحلى الماء! متأكدون أنكم لا تريدون؟ ما زال في الوقتِ متسع… أفطروا وأنقذوا كرامتَكم!'],['حمزة','(يغلي — يتقدم خطوة… فيمسكه صلاح الدين من كتفه)'],['صلاح الدين','(هادئاً وعيناه على الخصم) احتفظْ بغيظِكَ للشباك يا حمزة… نحن لا نلعبُ ضدَّهم فقط — نلعبُ أمامَ من تُعرَضُ عليه الأعمال. أرِهِ ما يصنعُ الصائمون.'],['حمزة','(يتنفس عميقاً… يبتسم فجأة ويستدير للملعب) صدقت… يا شباب: الهجمةُ القادمةُ باسمِ العطش!']]},
{h:'م٤ · خارجي — الملعب، ذروة ونهاية المباراة',d:'الدقائق الأخيرة والنتيجة تعادل: عرضية من معاذ (الهادئ الذي يمرر ذهباً)، صلاح الدين يسقطها بصدره، وحمزة — بكل غيظه المدَّخر — يسددها صاروخاً في الزاوية. هدف الفوز! العصبة تنهار على التراب حضناً واحداً لاهثاً — لا طاقة للركض احتفالاً. لاعب الخصم المستفز يقترب… ويمد يده.',dlg:[['لاعب الخصم','(يصافح بإكبار حقيقي) لعبتم الشوطَ الثاني في هذا الفرن… بلا قطرةِ ماء. أنا لا أفهمُكم… لكني أحترمُكم. ما سرُّكم؟'],['صلاح الدين','(لاهثاً ومبتسماً) السرُّ أن للجوعِ الذي تختارُهُ طعماً آخر… تعالَ اكسرْهُ معنا عندَ المغرب وستفهم — إفطارُنا اليوم على سطحِ بيتِ جدي، وأنتَ أولُ المدعوين!']],vo:'وجاءَ فعلاً — هو واثنان من فريقِه. وهكذا اكتشفنا فائدةً ما وعدَنا بها الشيخ: الصيامُ يفتحُ من القلوبِ ما لا تفتحُهُ الأهداف.'},
{h:'م٥ · خارجي — سطح بيت الجد، مغرب النصر',d:'مشهد الختام الذهبي: السطح عند الغروب، بساط عليه تمر وماء ولبن الجدة وصينية كنافة «للفائزين». العصبة + ثلاثة من الخصوم القدامى، والأذان يقترب. صمت الثواني الأخيرة — كل العيون على أطباق التمر والشفاه الجافة تبتسم.',dlg:[['المؤذن','(اللهُ أكبر… اللهُ أكبر)'],['الجميع','(تمرة أولى وماء — آهات ارتياح جماعية وضحك) ذهبَ الظمأُ وابتلتِ العروقُ وثبتَ الأجرُ إن شاءَ الله!'],['الشيخ محمود','(طلع عليهم فجأة من باب السطح — دعاه الجد سراً) هنيئاً يا رجال! جئتُ أحملُ لكم بشارتين: الأولى — للصائمِ فرحتان: فرحةٌ عندَ فطرِهِ وفرحةٌ عندَ لقاءِ ربِّه… وأنا أرى الأولى في وجوهِكم الآن. والثانية — (يجلس بينهم) من ملكَ بطنَهُ يا أبنائي… ملكَ نفسَه. ومن ملكَ نفسَه… لم يملكْهُ أحد: لا شهوةٌ ولا شاشةٌ ولا خوف. والأممُ الحرة… لا يبنيها إلا نفوسٌ حرة. أنتم الليلةَ تدربتم على الحرية.'],['صلاح الدين','(يرفع كوب اللبن كنخب الأبطال) على الحرية إذن… واثنينِ وخميسِ الأسبوعِ القادم!']],vo:'ثمانيةُ أيامٍ صمناها ذلك الصيف… ثم صارتْ عادةَ عمر. وكلما اشتدتْ عليَّ الحياةُ لاحقاً — وستشتدُّ — كنتُ أعودُ لسلاحِ الاثنينِ والخميس: أرمِّمُ به إرادتي كما يرمِّمُ الفارسُ درعَه. جرِّبوهُ يا أصدقائي… فالجوعُ المختارُ يصنعُ أحراراً.'}],
msg:'تُعرض الأعمال الاثنين والخميس: الجوع المختار يصنع الأحرار — ومن ملك بطنه ملك نفسه ولم يملكه أحد.',apply:'جرّب صيام يوم اثنين أو خميس هذا الأسبوع (بإذن أهلك) — واجعل فيه عملاً صالحاً إضافياً يُرفع مع صيامك.'},

{n:54,t:'يومَ غضبَ حمزة',ic:'🔥',age:'١٢ سنة ونصف',loc:'ملعب الحي',corner:'heart',goal:'كظم الغيظ وإصلاح ذات البين: «ليس الشديد بالصرعة» بين الأصحاب',chars:['صلاح الدين','حمزة','معاذ','اللاعب الخشن (زياد)','الجدة'],
scenes:[
{h:'م١ · خارجي — ملعب الحي، اشتعال تدريجي',d:'مباراة ودية تتحول: زياد — لاعب ضخم من الفريق الخصم معروف بخشونته — يستهدف معاذ النحيل تحديداً: عرقلة أولى (يتجاوزها معاذ بابتسامة)، دفعة ثانية أقوى، ثم الثالثة: قدم متعمدة تسقط معاذ على الحصى — دم على ركبته وشحوب على وجهه.',dlg:[['زياد','(واقفاً فوقه بلا اعتذار) الملعبُ للرجال… من يخفْ على ركبتيهِ يلعبِ الشطرنج.'],['حمزة','(يرى الدم — والدنيا تحمرُّ في عينيه. يقطع الملعب كالقذيفة نحو زياد، قبضتاه معقودتان، والفريقان يتراكضون خلفه — ثوانٍ عن كارثة جماعية)']],vo:'حمزة… أطيبُ قلبٍ في الحارة وأسرعُ غضبٍ فيها. وفي تلك الثواني رأيتُ المشهدَ بعينِ قائدٍ لأولِ مرة: صديقي مظلوم، وغضبُهُ حق… لكنَّ عراكاً واحداً سيحرقُ حارتين. وكان عليَّ أن أختارَ في ثانيتين.'},
{h:'م٢ · خارجي — قلب الملعب، التدخل',d:'صلاح الدين لا يصرخ «اهدأ» من بعيد — يركض ويعترض حمزة قبل خطوتين من زياد، ويفعل ما لا يتوقعه أحد: يحتضنه. حضن كامل يقيّد الذراعين، وفمه على أذن ابن عمه.',dlg:[['صلاح الدين','(هامساً بقوة والجسدان يرتجفان) حمزة… حمزة اسمعْ صوتي. أعوذُ باللهِ من الشيطانِ الرجيم — قلها. قلها يا حمزة!'],['حمزة','(يزأر محاولاً الانفلات) رأيتَ ما فعل؟! الدمُ يا صلاح الدين! دمُ معاذ!'],['صلاح الدين','(لا يفلت الحضن) رأيتُ… ورأيتُ شيئاً آخر: رسولَ اللهِ ﷺ يقول: ليسَ الشديدُ بالصُّرعة — إنما الشديدُ الذي يملكُ نفسَهُ عندَ الغضب. زيادُ أسقطَ معاذاً… أتريدُ أن يُسقطَكَ أنتَ أيضاً؟ غضبُكَ حقّ — فلا تجعلْهُ باطلاً بلكمة. قلها…'],['حمزة','(ارتجاف الكتفين يهدأ تدريجياً… وبصوت مخنوق) أعوذُ… أعوذُ باللهِ من الشيطانِ الرجيم. (يلتفت لمعاذ الجالس أرضاً) لكنه… لن يمرَّ الأمرُ هكذا.'],['صلاح الدين','(يفك الحضن ويمسك كتفيه) لن يمرَّ هكذا — أعدُك. سيمرُّ بالعدل… لا بالعراك. والعدلُ أوجع.']]},
{h:'م٣ · خارجي — حافة الملعب، جلسة الإنصاف',d:'صلاح الدين يفعلها بجرأة مدهشة: ينادي قائد الفريق الخصم وزياد نفسه لحافة الملعب — «جلسة حكم» ميدانية والفريقان شهود. معاذ جالس وركبته تُربط بمنديل.',dlg:[['صلاح الدين','(بهدوء قاضٍ صغير) يا زياد… ثلاثُ عرقلاتٍ لنفسِ اللاعب، والثالثةُ أدمت. الملعبُ شاهد. نحن لا نريدُ عراكاً — نريدُ كلمةً واحدةً منك: أخطأت.'],['زياد','(مكابراً) هذه كرة… فيها احتكاك! من لا يتحمل—'],['قائد فريقه','(يقاطعه محرجاً) يا زياد… كلُّنا رأينا. الثالثةُ ما كانت احتكاكاً. قلها وأرِحنا — أنتَ تحرجُ فريقَكَ كلَّه.'],['زياد','(محاصر بشهادة فريقه نفسه… ينظر للأرض طويلاً… ثم يرفع رأسه نحو معاذ) …أخطأت. الثالثةُ كانت بقصد — استفزني هدوءُك. (يمد يده) سامحني يا معاذ.'],['معاذ','(يرفع رأسه بابتسامته الهادئة رغم الألم… ويمد يده) مسامح. والعفوُ عندَ المقدرةِ يا زياد… أحلى من عشرةِ أهداف. لكن بشرط: (يبتسم أوسع) تعلِّمُني ضربةَ رأسِكَ القوية — حلالاً هذه المرة!'],['الفريقان','(ينفجرون ضحكاً — التوتر يذوب دفعة واحدة)']],vo:'انظروا ماذا حدث: غضبٌ كُظم، وظالمٌ اعترف، ومظلومٌ عفا — والنتيجة: ملعبٌ يضحكُ بدل حارتين تشتعلان. الإصلاحُ يا أصدقائي ليس ضعفاً… الإصلاحُ هندسةٌ يتقنُها الأقوياءُ وحدَهم.'},
{h:'م٤ · خارجي — سطح بيت الجد، ضيافة الصلح',d:'المساء نفسه. صلاح الدين يكمل الهندسة: دعوة الفريقين — بزياد نفسه — لشاي المصالحة على السطح. الجدة خديجة (أُخبرت بالقصة) تصعد بصينية ضخمة: شاي بالميرمية وكعك بعجوة.',dlg:[['الجدة','(توزع الشاي وتتعمد أن تبدأ بزياد) اشرب يا حبيبي… (تربت كتفه) سمعتُ أنكَ قلتَ اليوم أصعبَ كلمةٍ عندَ الرجال: أخطأت. تعرفُ شو بيقول أهلُ القدس؟ اللي بيعترفْ بغلطتُه… بيتُهُ عامر. اشربْ وعُدْ لنا كلَّ جمعة.'],['زياد','(يمسك الكاس محرجاً من الحنان غير المتوقع)… حجة، أنا آذيتُ حفيدَ… يعني صديقَ حفيدِك. لماذا تكرمينني؟'],['الجدة','(تضحك) لأن الكرمَ يا ولدي بيربّي أحسنْ من الزعل. والسفرةُ اللي بتجمعِ المتخاصمين… بتفتحْ لها السما شبابيك.'],['حمزة','(يهمس لصلاح الدين وهو يراقب زياد يذوب وسط الضيافة) …كدتُ أكسرُ أنفَهُ الظهر. والآن جدتُكَ تطعمُهُ كعكاً. (يهز رأسه) أيهما انتصر؟'],['صلاح الدين','(يرفع كاس الشاي) أنتَ انتصرت يا حمزة… لحظةَ قلتَ «أعوذ بالله». كلُّ ما بعدَها… ثمارُ تلكَ الكلمة.']]},
{h:'م٥ · خارجي — السطح، خاتمة الدرس',d:'الضيوف انصرفوا. العصبة الثلاثية وحدها تحت النجوم، معاذ يفرد ساقه المربوطة. لحظة مصارحة هادئة.',dlg:[['حمزة','(يكسر الصمت) عندي اعتراف… الغضبُ الذي ركبني اليوم — يركبُني كثيراً. في البيت، في الصف… أخافُ منه. كيف تتحكمُ أنتَ يا صلاح الدين؟ لا أراكَ تغضب.'],['صلاح الدين','أغضب! لكني تدربت — ولك السرُّ كاملاً، وصفةُ النبي ﷺ نفسِه: إذا غضبتَ فقل أعوذُ بالله — تطردُ الوقّاد. وإن كنتَ واقفاً فاجلس، وإن كنتَ جالساً فاضطجع — تكسرُ الاندفاعة. وإن بقيَ الجمرُ… فتوضأ: الغضبُ جمرةٌ والماءُ يطفئُها. ثم قاعدتي أنا: لا تتكلمْ وأنتَ غاضب أبداً — الكلمةُ الغاضبةُ سهمٌ… لا يعودُ للجعبة.'],['معاذ','(يضيف بهدوئه) وأزيدُكَ يا حمزة آيةً تحفظُها: والكاظمينَ الغيظَ والعافينَ عن الناس واللهُ يحبُّ المحسنين… ترتيبٌ عجيب: اكظمْ أولاً، ثم اعفُ، ثم أحسِنْ — درجةٌ فوقَ درجة. وأنتَ اليومَ صعدتَ الأولى.'],['حمزة','(ينظر للنجوم طويلاً… ثم يبتسم) اكتبوها في دفترِ العهد: «حمزة… بدأ يصعد».']],vo:'وصعدَ فعلاً — سنةً بعدَ سنة، حتى صارَ حمزةُ نفسُهُ من يُطفئُ غضبَ الرجالِ في مواقفَ أكبرَ من ملاعبِ الحواري بكثير. فيا صاحبَ الغضبِ السريع: لا تيأسْ من نفسِك… الغضبُ حصانٌ جامح — وقد رأيتَ في حلقةِ ريح: الجوامحُ تُروَّض.'}],
msg:'ليس الشديد بالصرعة: أعوذ بالله ثم اجلس ثم توضأ — والكاظمين الغيظ درجةٌ يصعدها من أراد أن يحبه الله.',apply:'عند أول غضب قادم: قل «أعوذ بالله من الشيطان الرجيم»، واجلس إن كنت واقفاً، وتوضأ — ثم تكلم.'},

{n:55,t:'حديقةُ الأيدي الصغيرة',ic:'🌻',age:'١٢ سنة ونصف',loc:'حديقة الحي — عمّان',corner:'social',goal:'العمل الجماعي وخدمة المكان: إماطة الأذى صدقة — والمبادرة لا تنتظر إذناً بالخير',chars:['العصبة الثلاثية','زياد','أبو خليل النجار','أهل الحي'],
scenes:[
{h:'م١ · خارجي — حديقة الحي، جولة الواقع المؤلم',d:'العصبة تقطع الحديقة العامة طريقاً مختصراً: أعشاب يابسة بطول الركب، أكياس وقناني مبعثرة، أرجوحة مكسورة تتدلى من سلسلة واحدة، ومقعد خشبي مخلوع. أم تسحب طفلها: «قلتُ لك لا تلعب هنا — زجاج!». عند السور: ثلاثة رجال من الحي يحتسون الشاي ويتذمرون.',dlg:[['رجل من الحي','حديقةٌ صارتْ خرابة! أين البلدية؟ أين المسؤولون؟ من سنتين ونحن نشكو!'],['رجل ثانٍ','اكتبنا شكوى… وناموا عليها. هذا حالُ الدنيا — كلٌّ يقول: ليس شغلي.'],['صلاح الدين','(يتوقف ويستمع… ثم يلتفت لرفيقيه وعينه على الأرجوحة المكسورة) سمعتما؟ سنتان من الشكوى… (يلتقط كيساً ويرميه في البرميل الصدئ) والشكوى يا شباب ليست عملاً. تعالوا هنا…']],vo:'في كلِّ حيٍّ في الدنيا حديقةٌ مثلُها… وناسٌ يشكون مثلَهم. والفرقُ بين حيٍّ يذبلُ وحيٍّ يزهر… ليس البلدية. الفرقُ ثلاثةُ فتيانٍ قرروا ذاتَ عصرٍ أن الشكوى ليست عملاً.'},
{h:'م٢ · خارجي — زاوية الحديقة، ولادة الخطة',d:'العصبة جلوس على المقعد المخلوع. صلاح الدين يفتح دفتر المشاريع (صار سميكاً مجرباً) ويكتب.',dlg:[['حمزة','ثلاثةٌ ننظفُ هذا كلَّه؟ نحتاجُ جيشاً يا رجل!'],['صلاح الدين','(يكتب) قاعدةُ مانشستر يا حمزة: نبدأ نحن ولو بثلاثة — الشرارةُ لا تحتاجُ جيشاً… الشرارةُ تصنعُه. الخطة: ثلاثُ جُمَع. الأولى تنظيف — نحن والأكياس. الثانية زراعة — جدي وعدني بشتلاتٍ من مشتلِه. الثالثة إصلاح — الأرجوحةُ والمقعد… وهذه تحتاجُ نجاراً.'],['معاذ','وقاعدتي أنا قبل البدء: نستأذن. البلديةُ والمختار — حتى لا يأتيَ من يقول: من أذنَ لكم؟ الخيرُ بالفوضى يتعطل… والخيرُ بالنظامِ يتضاعف.'],['صلاح الدين','(يكتب «الإذن: معاذ» ويبتسم) ولهذا أنتَ وزيرُ الحكمةِ في العصبة. حمزة: وزيرُ العضلات. أنا: وزيرُ الإزعاج — سأطرقُ أبوابَ الحيِّ كلَّها!']]},
{h:'م٣ · خارجي — الحديقة، مونتاج الجُمَع الثلاث',d:'مونتاج تصاعدي هو قلب الحلقة: (الجمعة ١) ثلاثة فتيان بقفازات وأكياس تحت شمس حارقة — المتذمرون الثلاثة يراقبون من السور باستغراب… طفلان ينضمان بفضول… ثم زياد يمر بكرته، يقف، ويرمي الكرة جانباً: «وزيرُ العضلات يحتاجُ مساعداً؟». (الجمعة ٢) الجد يصل ومعه عربة شتلات — ورد وياسمين وزيتونة صغيرة! نساء الحي يرسلن صواني عصير، والمتذمرون الثلاثة… يحفرون! (الجمعة ٣) المفاجأة الكبرى.',dlg:[['أبو خليل النجار','(ظهر فجأة بعدة نجارته كاملة — كان يراقب من دكانه ثلاث جمعات) من أصلحَ نيتَهُ… أصلحنا له خشبَه! أنا آخذُ أجرةً من كلِّ الحي… إلا من ثلاثةِ فتيانٍ علَّموا الكبارَ الحياء. أين هذه الأرجوحةُ المسكينة؟'],['حمزة','(هامساً لصلاح الدين وهما يحملان اللوح مع النجار) الشرارةُ صنعتِ الجيش…'],['صلاح الدين','(يبتسم ويكمل الجملة) والخيرُ مُعدٍ كالضحكة — انظرْ حولك!']],vo:'ثلاثُ جُمَع… من ثلاثةٍ إلى ثلاثين. حتى البلديةُ — التي «نامتْ على الشكوى سنتين» — أرسلتْ في الأسبوعِ الرابعِ عمالاً يدهنون السورَ ومصباحين جديدين: الجهاتُ الرسميةُ يا أصدقائي تستيقظُ حين ترى الناسَ استيقظوا.'},
{h:'م٤ · خارجي — الحديقة، لمسة الاسم',d:'الحديقة اكتملت: عشب مقصوص، ورود مصفوفة، أرجوحة تتأرجح بطفلين، ومقعد جديد يجلس عليه المتذمرون الثلاثة… يبتسمون هذه المرة. عند المدخل: أبو خليل يثبت لوحة خشبية صنعها سراً — محفور عليها بحرق الخشب: «حديقةُ الأيدي الصغيرة».',dlg:[['أبو خليل','(يكشف اللوحة أمام الجمع) الاسمُ من عندي — واحتجاجُ ممنوع! فهذه الحديقةُ ما أحيتْها ميزانياتٌ ولا اجتماعات… أحيتْها أيدٍ صغيرةٌ وقلوبٌ كبيرة.'],['المختار','(يقص شريطاً رمزياً من خيط صوف الجدة خديجة، ضاحكاً) باسم الحي… شكراً لحكومةِ الفتيان! وأولُ قرارٍ رسمي: جمعةُ كلِّ شهرٍ — يومُ صيانةٍ جماعي. من يتخلفْ… يحاسبُهُ صلاح الدين!'],['صلاح الدين','(يرفع يده معترضاً وسط الضحك) لا محاسبة! عندنا قاعدةٌ أجمل: إماطةُ الأذى عن الطريقِ صدقة — والصدقةُ لا تحتاجُ شرطياً… تحتاجُ من يتذكرُ أجرَها.']]},
{h:'م٥ · خارجي — الحديقة، لقطة الغروب الختامية',d:'الغروب. العصبة + زياد جلوس على العشب الجديد، والجد يسقي الزيتونة الصغيرة التي غرست في قلب الحديقة. أطفال يتأرجحون خلفهم وضحكاتهم تملأ المكان.',dlg:[['الجد','(يعتدل عن الزيتونة ويتأمل الحديقة) أتدرون ماذا أرى؟ أرى حارتي قبلَ خمسين سنة… كنا نعمِّرُ هكذا: أهلُ الحيِّ سواعدُ بعضِهم. ثم جاءَ زمنُ «ليس شغلي»… فذبلَ كلُّ شيء. أنتم اليومَ ما أصلحتم حديقةً يا أولادي… أعدتم سنةً كادت تموت: سنةَ العمارةِ بالأيدي.'],['صلاح الدين','(ينظر للزيتونة الصغيرة ثم لجده) جدي… زيتونتُكَ هذه — كم تحتاجُ لتثمر؟'],['الجد','خمسَ سنين… ربما سبعاً. (يبتسم ابتسامته العارفة) لماذا؟ أتستعجلُ الثمر؟'],['صلاح الدين','(يهز رأسه) لا… أحسبُ فقط: كم حديقةً نستطيعُ أن نحييَ قبلَ أن تثمر.']],vo:'كانت حديقةَ الأيدي الصغيرة الأولى… ولم تكنِ الأخيرة. فالمشروعُ الذي تلمحونَهُ يكبرُ في دفتري حلقةً بعد حلقة — بدأ صندوقَ كعكٍ في مانشستر، وصارَ اليومَ حديقة… واسألوا أنفسَكم: ماذا يصيرُ غداً؟ تابعوني.'}],
msg:'الشكوى ليست عملاً: ابدأ ولو بثلاثة فالشرارة تصنع الجيش — وإماطة الأذى صدقة تعيد سنة العمارة بالأيدي.',apply:'اختر بقعة مهملة قريبة (درج العمارة، ركن الصف، رصيف البيت) ونظّفها هذا الأسبوع مع صديقين — بلا انتظار شكر.'},

{n:56,t:'صرتُ أحلمُ بالعربية',ic:'💬',age:'١٣ سنة إلا قليلاً',loc:'عمّان',corner:'academy',goal:'ثمرة المثابرة اللغوية: من التعثر إلى التذوق — وفهم القرآن مباشرة',chars:['صلاح الدين','الأستاذ فؤاد','الشيخ محمود','العائلة'],
scenes:[
{h:'م١ · داخلي — غرفة صلاح الدين، صباح الاكتشاف',d:'يستيقظ فجأة قبل المنبه، يجلس في فراشه بعينين متسعتين كمن رأى أعجوبة. ينزل الدرج راكضاً بثياب النوم إلى مائدة الفطور.',dlg:[['صلاح الدين','(لاهثاً) اسمعوا! البارحة… حلمتُ حلماً كاملاً — بالفصحى! كنتُ أخطبُ في ناسٍ كثيرين، وأقول: «أيها الناس، إن الأبوابَ لا تُفتَحُ بالتمني» — بالضمِّ والفتحِ والكسر! حتى في الحلم كنتُ أُعرِبُ يا بابا!'],['أيوب','(يضع كوب الشاي ببطء ويتبادل نظرة ذات معنى مع مريم)… أتعرفُ ماذا يعني هذا يا صلاح الدين؟ اللغةُ لا تسكنُ الأحلامَ إلا إذا ملكتِ القلب. انتهتِ الغربةُ الثانية يا بني — لسانُكَ وصلَ إلى أرضِه.'],['الجدة','(من المطبخ) خبِّروهُ يحلمْ لنا بالياسمين كمان — أحلامُ الفصحى مباركة!']],vo:'سنتان ونصفٌ من دفترٍ أخضرَ وثلاثِ كلماتٍ في اليوم… والثمرةُ جاءتني نائماً. هكذا تعملُ الجهودُ الصغيرةُ المتراكمةُ يا أصدقائي: تحفرُ في الصمتِ طويلاً… ثم تفيضُ فجأةً حتى في أحلامِك.'},
{h:'م٢ · داخلي — الصف، تكليف المسابقة',d:'الأستاذ فؤاد يدخل الحصة حاملاً ظرفاً رسمياً بشعار وزارة التربية.',dlg:[['الأستاذ فؤاد','مسابقةُ الإلقاءِ للمحافظة — كلُّ مدرسةٍ ترشحُ طالباً واحداً يلقي قصيدةً أمامَ لجنةٍ وجمهور. وقد رشحتُ باسمِ مدرستِنا… (يتعمد الصمت والصف يحبس أنفاسه) صلاحَ الدين.'],['الصف','(همهمة — وصوت من الخلف: «ابنُ مانشستر؟! في الإلقاء؟!»)'],['الأستاذ فؤاد','(يلتفت لصاحب الصوت بهدوء) نعم — ابنُ مانشستر الذي ضحكَ بعضُكم من لسانِهِ قبل سنتين ونصف. رشحتُهُ لسببين: الأول أن لغتَهُ اليومَ تُدرَّس. والثاني أهم — القصيدةُ المختارةُ هذا العام… عن القدس. (يضع الورقة أمام صلاح الدين) ومن يلقي عن القدس… يجبُ أن تكونَ القدسُ في دمِه، لا في حنجرتِه فقط.'],['صلاح الدين','(يقرأ عنوان القصيدة وتلمع عيناه… يرفع رأسه) متى المسابقة؟']]},
{h:'م٣ · داخلي — حلقة الفجر، لحظة سورة يوسف',d:'قبل المسابقة بأيام — المشهد الأعمق في الحلقة. مراجعة الحفظ وصلت سورة يوسف. صلاح الدين يتلو من حفظه الجديد: «اذهبوا بقميصي هذا…» — وفجأة يتوقف صوته عند «ارجعوا إلى أبيكم». يحاول الإكمال… فتنهمر دموعه بلا مقدمات. الحلقة تصمت. الشيخ محمود يرفع يده: لا يقاطعْهُ أحد.',dlg:[['الشيخ محمود','(بعد أن يهدأ… بصوت أبوي) ما الذي أبكاكَ يا بني؟ الآيةُ نفسُها قرأتَها قبل سنتين في جزءِ الحفظِ ولم تبكِ.'],['صلاح الدين','(يمسح عينيه محرجاً) قبل سنتين يا شيخي… كنتُ أحفظُ الحروف. أما الآن… الآن أفهمُ بلا ترجمة! سمعتُ إخوةَ يوسفَ يتوسلون، ورأيتُ يعقوبَ الأعمى من الحزن، وشممتُ ريحَ القميص! الكلماتُ صارت… صارت حية! (يرفع المصحف) يا شيخي — هل كان هذا الجمالُ كلُّهُ هنا طوالَ الوقت… وأنا لا أراه؟!'],['الشيخ محمود','(يلتفت للحلقة كلها ببطء) اسمعوا هذا السؤالَ يا أبنائي واحفظوه… هذا سؤالُ من فُتحَ له. نعم يا صلاح الدين — كان هنا طوالَ الوقت، وسيزدادُ ما ازددتَ فهماً: بحرٌ لا ساحلَ له. ولهذا قلنا لكم دوماً: تعلموا العربيةَ… فإنها من الدين. ليست لغةَ قوم — إنها مفتاحُ كنزِ السماء.']],vo:'تلك الدمعةُ عند «ارجعوا إلى أبيكم» أغلى ثمارِ دفتري الأخضر. فيا من يتعلمُ العربية: اصبرْ… فبينك وبينَ البكاءِ من الجمالِ سنتان من دفترٍ صغير.'},
{h:'م٤ · داخلي — قاعة المسابقة، الإلقاء',d:'قاعة كبيرة: لجنة، وطلاب من عشرين مدرسة. متسابقون يمرون — إلقاء جيد ومتوسط. اسمه يُنادى: «صلاح الدين أيوب — يلقي: يا قدس». يصعد… يغمض عينيه ثانية (طقس المنبر القديم: من قلبك)… ويبدأ. لا نسمع القصيدة كاملة — لقطات متقاطعة: يداه ترسمان الأسوار في الهواء، اللجنة تعتدل في مقاعدها واحداً بعد الآخر، طالب في الصف الأخير يتوقف عن العبث ويعتدل، والمقطع الأخير يقوله وعيناه تلمعان — فيصمت قلبُ القاعة ثم ينفجر تصفيقاً طويلاً.',dlg:[['رئيس اللجنة','(يرفع ورقة النتيجة بعد المداولة) المركزُ الأول — بإجماعِ اللجنة: صلاحُ الدين أيوب. (يضيف خارج البروتوكول) وأسمحُ لنفسي بكلمة: يا بني، نحن نحكِّمُ مخارجَ الحروفِ والوقفات… لكنكَ أعطيتَنا شيئاً فوقَ التحكيم: أسمعتَنا القدسَ نفسَها. من أين لفتىً في الثالثةَ عشرةَ هذا؟'],['صلاح الدين','(يمسك الميكروفون بأدب) من جبلٍ اسمُهُ نيبو يا سيدي… وقفتُ عليه فرأيتُها. ومن يرَ القدسَ بعينِه… لا يلقي عنها إلقاءً — يشتاقُ بصوتٍ عالٍ.']]},
{h:'م٥ · داخلي — غرفته، رسالة توم الشهرية',d:'الليل. الكأس الذهبية الصغيرة على المكتب بجانب صورة توم القديمة. صلاح الدين يكتب رسالته الشهرية — نراه يكتب ونسمع صوته.',dlg:[['صلاح الدين','(صوته يقرأ ما يكتب) «عزيزي توم… فزتُ اليومَ بمسابقةِ الإلقاء — بقصيدةٍ عن مدينةِ أحلامي. لكن ليس هذا خبري المهم. خبري أني بكيتُ هذا الأسبوعَ وأنا أقرأ قصةَ نبيٍّ اسمُهُ يوسف — بكيتُ لأني فهمتُ كلَّ كلمةٍ بلا وسيط. يا توم… أنتَ تقرأ الترجمةَ التي أهديتُك، وهي نافذةٌ جميلة. لكن صدقني: تعلمِ العربية. إنها ليست لغةً يا صديقي… إنها بابٌ إلى نورٍ لا يوصف. وأنا أعرفُكَ من يومِ برجِ المكعبات: أنتَ تحبُّ الأبواب». (يطوي الرسالة ويضعها في الظرف ويطفئ النور)']],vo:'وبعد سنواتٍ سيخبرُني توم أنه احتفظَ بتلك الرسالةِ تحديداً في جيبِ معطفِه شهوراً… وأنها كانت من الأصواتِ التي قادتْهُ إلى ما تعرفون. الكلمةُ الصادقةُ يا أصدقائي سهمٌ لا يخطئ — فقط قد يطولُ طيرانُه.'}],
msg:'تعلموا العربية فإنها من الدين: بينك وبين البكاء من جمال القرآن دفترٌ أخضر وصبر سنتين — إنها باب إلى نور لا يوصف.',apply:'اقرأ اليوم صفحة من القرآن وحاول فهمها وحدك، ثم راجع التفسير الميسر — ولاحظ الفرق حين تفهم ما تتلو.'},

{n:57,t:'عشرُ ليالٍ في بيتِ الله',ic:'🕋',age:'١٣ سنة إلا قليلاً',loc:'مسجد الحي — العشر الأواخر',corner:'ibada',goal:'الاعتكاف المصغر وليلة القدر: تذوق الخلوة بالله — خير من ألف شهر',chars:['صلاح الدين','أيوب','الجد','العصبة','الشيخ محمود'],
scenes:[
{h:'م١ · داخلي — بيت الجد، حقيبة الاعتكاف',d:'اليوم العشرون من رمضان. صلاح الدين يحزم حقيبة صغيرة بإشراف جده — أول «اعتكاف فتيان» في حياته: ثلاث ليالٍ في المسجد مع أبيه والجد والعصبة.',dlg:[['الجد','(يراقب الحقيبة) أخرجِ اللعبةَ الإلكترونية… والقصص. (يبتسم لاعتراض عينيه) قلتَ تريدُ اعتكافَ الرجال؟ حقيبةُ المعتكفِ ثلاثةُ أشياء: مصحفٌ، وسواكٌ، وبطانية. الاعتكافُ يا حبيبي فنُّ التخفف — تتركُ الدنيا خارجَ البابِ لتجدَ ما هو أثقلُ منها داخلَه.'],['صلاح الدين','(يخرج الأغراض… ثم يتردد عند شيء أخير) والدفتر؟ دفترُ الدعاء — كتبتُ فيه أسماءَ كلِّ من أحب…'],['الجد','(يضع الدفتر في الحقيبة بنفسه) هذا… هذا من عدةِ المعتكفين الكبار. خذْه.']],vo:'مصحفٌ وسواكٌ وبطانيةٌ ودفترُ أسماء… أخفُّ حقيبةٍ حزمتُها في حياتي — لأثقلِ رحلةٍ سافرتُها: ثلاثُ ليالٍ إلى الداخل.'},
{h:'م٢ · داخلي — المسجد، ليل الاعتكاف الأول',d:'المسجد بعد التراويح: الزحام انصرف وبقي المعتكفون — عشرون رجلاً وأربعة فتيان. إضاءة خافتة. مشهد يرصد «أصوات الليل التي لا تُسمع نهاراً»: رجل يبكي في جوف المسجد بكاء خفياً، آخر يردد آية واحدة عشرات المرات («إياك نعبد وإياك نستعين»)، همس دعاء من كل زاوية، وصفحات تُقلب.',dlg:[['صلاح الدين','(هامساً لأبيه تحت البطانية المشتركة) بابا… ذلك الرجلُ يبكي منذ ساعة. هل أصابَهُ مكروه؟'],['أيوب','(هامساً) أصابَهُ أجملُ مكروه: وجدَ نفسَهُ أمامَ الله. اسمعْ يا صلاح الدين… في النهارِ نلبسُ أقنعةَ القوة. وفي جوفِ الليل، في بيتِ الله، تسقطُ الأقنعةُ كلُّها — فيبكي الكبارُ كالأطفال. لا تخفْ من هذا البكاء… تعلمْهُ. فالعينُ التي تبكي من خشيةِ اللهِ لا تمسُّها النار.']]},
{h:'م٣ · داخلي — المسجد، درس الصمت',d:'اليوم الثاني، بعد العصر. صلاح الدين أنهى ورده وضجر قليلاً — يتنقل، يقلب المصحف، ينظر للساعة. الجد يراقبه من زاويته ثم يشير له: تعال. يجلسان متجاورين مستندين للجدار — والجد… لا يقول شيئاً. عشر دقائق كاملة من الصمت (يجرؤ المشهد على الصمت الحقيقي — أصوات المسجد الخافتة فقط).',dlg:[['صلاح الدين','(لا يحتمل أخيراً — هامساً) جدي… لماذا لا نتكلم؟'],['الجد','(عيناه مغمضتان) نحن نتكلم… أنتَ لم تتعلمْ لغتَنا بعد. (يفتح عينيه) يا صلاح الدين: علَّموكَ أن العبادةَ قراءةٌ وذكرٌ وصلاة — وصدقوا. لكن نسيَ الناسُ عبادةً كان يفعلُها نبيُّكَ ﷺ في غارِ حراء قبلَ الوحي: الخلوة… التفكر… الصمتُ الممتلئ. اصمتْ وفكِّر: من أنا؟ ولماذا خُلقت؟ وإلى أين؟ جرِّبْ — عشرُ دقائقَ فقط… لكن اصمتْ من الداخلِ أيضاً.'],['صلاح الدين','(يغمض عينيه… الكاميرا تقترب من وجهه ببطء والأصوات تخفت… دقيقة كاملة… ثم يفتحهما وفيهما شيء جديد) جدي… في الصمتِ أسئلةٌ كثيرة.'],['الجد','(يبتسم) وفي طولِ الصمت… تبدأ الأجوبة.']],vo:'درسُ الصمتِ ذاك… أثمنُ ما خرجتُ به من الاعتكافِ كلِّه. في زمنٍ سيمتلئُ ضجيجاً — شاشاتٍ وأصواتاً لا تسكت — سيصيرُ ربعُ ساعةِ الصمتِ اليومي حصني السري. من لا يخلو بنفسِهِ يا أصدقائي… تضيعُ منه نفسُه.'},
{h:'م٤ · داخلي — المسجد، ليلة السابع والعشرين',d:'الليلة المرجوة. المسجد امتلأ من جديد — قيام طويل. في الثلث الأخير يوقظ أيوب ابنه النائم على بطانيته برفق: «القنوت… قم يا حبيبي، فقد لا تدركُ مثلَها». المشهد المهيب: الإمام يقنت والمسجد كله أيدٍ مرفوعة ونشيج — الجد رافع يديه المرتجفتين ودموعه على الكوفية، حمزة يبكي (حمزة!)، ومعاذ ساجد لا يرفع. صلاح الدين يرفع يديه… ويفتح دفتر الأسماء أمامه.',dlg:[['صلاح الدين','(همس دعائه يعلو تدريجياً مع القنوت — أول دعاء «كبير» في حياته) اللهم… اغفرْ لأمي وأبي واجزِهما عني خيرَ الجزاء… اللهم احفظْ جدي وأطلْ عمرَهُ على طاعتِك، واجمعْهُ ببيتِهِ الذي خرجَ منه… اللهم اهدِ توم — يا رب، توم الذي يقرأ كتابَك، افتحْ قلبَهُ للنور… اللهم فرِّجْ عن أنس وجدتِهِ وأهلِ غزة… وارحمْ كريماً وأهلَ المخيم… (يتهدج صوته ويقبض على المفتاح المرسوم في دفتره) اللهم… اللهم اكتبني من جندِ فتحِ المسجدِ الأقصى. إن لم أكن فارسَها… فاجعلني حجراً في طريقِها. (تظهر الجملة مكتوبةً على الشاشة كما ستحفظها أجيال المشاهدين)']],vo:'لا أعرفُ إن كانت ليلةَ القدرِ حقاً… اللهُ وحدَهُ يعلم. أعرفُ فقط أن شيئاً في صدري انفتحَ تلك الليلةَ ولم ينغلقْ بعدَها أبداً. بعضُ الليالي يا أصدقائي… تَزِنُ عمراً.'},
{h:'م٥ · خارجي — ساحة المسجد، فجر الخروج',d:'صباح انتهاء الاعتكاف. المعتكفون يتعانقون عند الباب. العصبة الثلاثية تخرج للشمس بعيون متعبة ووجوه مضيئة — ذلك التناقض الجميل.',dlg:[['حمزة','(يمط ذراعيه) ثلاثُ ليالٍ بلا جوال… وأقسمُ ما اشتقتُ له إلا مرتين!'],['معاذ','(يبتسم) تحسنٌ عظيم — العامَ الماضي كنتَ ستشتاقُ عشرين.'],['صلاح الدين','(يتوقف على عتبة المسجد ويلتفت للداخل نظرة أخيرة)… أتعرفان بمَ أشعر؟ كمن خرجَ من غارِ حراءٍ صغير. دخلنا فتياناً عاديين… وخرجنا نحملُ شيئاً. لا أعرفُ اسمَهُ بعد — لكني أشعرُ بثقلِهِ هنا. (يضع يده على صدره)'],['الشيخ محمود','(خلفهم عند الباب — سمع الكلمة) اسمُهُ «العهدة» يا صلاح الدين… كلُّ من خلا باللهِ صادقاً خرجَ يحملُ عهدة. وسترى قريباً — قريباً جداً — أين تضعُها. (ينظر إليه نظرة طويلة ذات معنى… تمهيداً لحلقة عهد المئذنة)']],vo:'«سترى قريباً أين تضعُها»… كان الشيخُ يعرفُ ما لا أعرف: أن عيدَ ميلادي الثالثَ عشرَ على الأبواب — وأن سطحَ المئذنةِ ينتظرُني بطقسٍ سيغيرُ حياتي. لكن هذه… حكايةُ الحلقةِ القادمة.'}],
msg:'الاعتكاف فن التخفف والصمت عبادة منسية: ليلة واحدة صادقة مع الله تزن عمراً — ومن خلا بالله خرج يحمل عهدة.',apply:'اجعل لك «ساعة اعتكاف» في أقرب جمعة: اجلس في المسجد بعد الصلاة ساعة — مصحف ودعاء وصمت، بلا هاتف.'},

{n:58,t:'مفتاحٌ يشبهُ مفتاحَنا',ic:'🗝️',age:'١٣ سنة',loc:'مخيم اللاجئين — قرب عمّان',corner:'quds',goal:'النصرة الميدانية: من رأى المعاناة عن قرب لا ينساها — إخوّة لا شفقة',chars:['العصبة','الجد','كريم','أم كريم'],
scenes:[
{h:'م١ · خارجي — مدخل المخيم، وصية الباب',d:'سيارة أجرة تنزل الجد والعصبة الثلاثية عند مدخل مخيم فلسطيني قرب عمّان — أزقة ضيقة وبيوت إسمنتية متلاصقة وأسلاك كهرباء متشابكة كالعروق. الجد يوقفهم قبل الدخول بعصاه.',dlg:[['الجد','قفوا… ثلاثُ وصايا قبل أن تخطوا: أولاً — هذه ليست سياحة، ولن تخرجوا منها بصورٍ للذكرى؛ ستخرجون بأسماءِ أصدقاء. ثانياً — ممنوعٌ نظراتُ الشفقة: أهلُ هذا المخيمِ أغنياءُ في كلِّ شيءٍ إلا المساحة. ثالثاً — ادخلوا إخوةً زائرين أهلَهم… لا محسنين يتفقدون فقراء. من لم يستطعْ… فليبقَ عند السيارة.'],['حمزة','(يبتلع) وكيف نعرفُ أن نظرتَنا… شفقة؟'],['الجد','(يبتسم) الشفقةُ تنظرُ من فوق… والإخوّةُ تنظرُ في العيون. هيا — عيونُكم في عيونِهم.']],vo:'ثلاثُ وصايا على بابِ مخيم… حملتُها معي بعدَها إلى كلِّ مخيماتِ الدنيا وقراها الفقيرة. فالمحتاجُ يا أصدقائي لا يجرحُهُ فقرُه… يجرحُهُ نظرةُ من جاءَ «يتفضلُ عليه».'},
{h:'م٢ · خارجي — أزقة المخيم، ضيق المكان وسعة الصدور',d:'مونتاج المشي في المخيم: زقاق بعرض الكتفين، نوافذ متقابلة تتحدث نساؤها، أطفال يلعبون كرة بشوارع بطول خمسة أمتار — ودفء مدهش: «تفضلوا اشربوا شاي!» من كل باب ثانٍ، رجل يعرف الجد فيهتف «أبو أيوب! نوَّرتَ المخيم!»، وعجوز توزع خبزاً ساخناً على أطفال الزقاق.',dlg:[['معاذ','(هامساً) عجيب… بيوتُهم أصغرُ من غرفي — وضيافتُهم أكبرُ من قصور.'],['الجد','(سمعها) حفظتَ الدرسَ الأولَ يا معاذ: المكانُ يضيقُ بقدرِ الجدران… ويتسعُ بقدرِ القلوب. هؤلاء أهلُ بلادي — خرجنا من فلسطينَ بمفاتيحِنا وكرمِنا… وتركنا لهم البيوت.']]},
{h:'م٣ · خارجي/داخلي — لقاء كريم',d:'زاوية الزقاق الرئيسي: فتى بعمرهم خلف بسطة خشبية صغيرة — كعك بسمسم مرصوص بعناية جيش. يبيع بحيوية ويحفظ حسابات ثلاثة زبائن في رأسه، وعلى ركبته مصحف صغير مفتوح يراجع منه بين زبون وزبون. الجد يقصده مباشرة — يعرفه.',dlg:[['الجد','كريم! كيف الخال؟ وكيف حالُ حفظِك؟'],['كريم','(يشرق وجهه) عمّي أبو أيوب! الخالُ الحمدُ لله… والحفظُ وصلَ الأنفال! (يلمح الفتية الثلاثة) أهلاً بالشباب — كعكةٌ لكلِّ واحدٍ على حسابي، عربونُ معرفة!'],['صلاح الدين','(يعترض بأدب) نأخذُها بشرطِ الدفع… فنحن نعرفُ قيمةَ البسطات. (يبتسم) أنا اشتغلتُ ساعةً على بسطةِ خضار — وأعرفُ أن «على حسابي» عندَ أهلِ البسطاتِ أغلى من قناطير.'],['كريم','(يضحك ويناوله الكعك) يا سلام! فتىً يفهمُ لغةَ الرزق! من أينَ أنتَ يا صاحبي؟'],['صلاح الدين','قصةٌ طويلة: وُلدتُ في مانشستر… وجذوري من هناك — (يشير غرباً بذقنه) من حيثُ مفتاحُ جدي.'],['كريم','(يتوقف عن لف الكعك… ويرفع عينيه ببطء) مفتاح؟… عندكم مفتاحٌ أيضاً؟']],vo:'«عندكم مفتاحٌ أيضاً؟»… ثلاثُ كلماتٍ فتحتْ بابَ أعمقِ صداقةٍ في حياتي. فبعضُ الناسِ تتعارفُ بالأسماء… ونحن — أبناءَ تلك البلاد — نتعارفُ بالمفاتيح.'},
{h:'م٤ · داخلي — بيت كريم، لقطة المفتاحين',d:'بيت من غرفتين تلمعان نظافة رغم بساطة كل شيء. أم كريم ترحب وتصر على الغداء («ما بيطلع حدا من بيتنا جوعان!»). وعلى الجدار الرئيسي — في إطار خشبي متواضع مصنوع يدوياً — مفتاح حديدي قديم كبير… توأمُ مفتاح الجد. الجد يقف أمامه مشدوهاً. لقطة المشهد: الجد يخرج مفتاحه من صدره ببطء ويرفعه بجانب المعلق — مونتاج متوازٍ يقرّب المفتاحين حتى يتطابقا في الكادر.',dlg:[['أم كريم','(بصوت هادئ من عمق الغرفة) مفتاحُ بيتِنا في يافا… علَّقَهُ جدُّ كريم وقال: ما بننسى. البيوتُ مختلفةٌ يا حجي… والمفاتيحُ واحدة.'],['الجد','(بصوت مبحوح، ومفتاحه يرتجف في يده) …بيتي في القدسِ القديمة. خرجنا وأنا بعمرِ هؤلاء. (يلتفت لأم كريم) البيوتُ مختلفةٌ والمفاتيحُ واحدة… واللهِ ما سمعتُ وصفاً أصدق. (يلتفت للفتية الأربعة المصطفين أمام الجدار) انظروا يا أولادي — احفظوا هذا الجدار: أمةٌ كاملةٌ علَّقتْ مفاتيحَها وانتظرت. والمفاتيحُ يا أولادي… لا تصدأ إذا بقيَ من يلمِّعُها بالذكرى. السؤالُ الوحيد: من جيلُ الأبواب؟'],['كريم وصلاح الدين','(يتبادلان نظرة طويلة… فتيان في الثالثة عشرة يفهمان فجأة أنهما وريثا القصة نفسها)']],},
{h:'م٥ · خارجي — طريق العودة، مشروع لا دموع',d:'المغرب. السيارة تبتعد عن المخيم — الفتية صامتون صمتاً ثقيلاً. ثم يكسر صلاح الدين الصمت بفتح دفتر المشاريع على ركبتيه.',dlg:[['صلاح الدين','(يكتب بقلم مشدود) نقطة أولى: كريم يقطعُ ساعتين مشياً لحلقةِ تحفيظٍ بعيدة — ومسجدُ حارتِنا فيه الشيخُ محمود: نرتبُ له مقعداً في الحلقةِ ومواصلات. نقطة ثانية: كعكُهُ أطيبُ من كعكِ مقصفِ مدرستِنا بمراحل — نعرضُ على المدير بيعَهُ في المقصف: دخلٌ ثابتٌ لبيتِهِم بكرامةِ تجارة… لا بصدقةٍ تجرح. نقطة ثالثة—'],['حمزة','(مقاطعاً بذهول) مهلاً! نحن عائدون من زيارةٍ هزتنا… وأنتَ تكتبُ خطة؟! ألا تحزن؟'],['صلاح الدين','(يرفع رأسه — وعيناه حمراوان فعلاً) أحزن… لكني تعلمتُ في مانشستر يا حمزة: الدموعُ التي لا تتحولُ مشروعاً… تجفُّ وتُنسى. أما المشروعُ فيبقى يعمل. (يلتفت للجد) جدي — أخبرني بصراحة: أينفعُ هذا؟ أم نحن صغارٌ على النفع؟'],['الجد','(ينظر إليه في مرآة السيارة طويلاً… ثم يبتسم أعمق ابتسمة في المرحلة) يا صلاحَ الدين… سألتَ سؤالَ الكبارِ فخذْ جوابَهم: النفعُ لا يسألُ عن العمر — يسألُ عن الصدق. نفِّذوا… وأنا خلفَكم.']],vo:'وخلالَ شهرٍ كان كريم سادسَ صفِّ الطامحين في حلقتِنا، وكعكُهُ يُباعُ في مقصفينِ لا مقصفٍ واحد. لكنَّ أثمنَ ما خرجنا به لم يكن المشاريع… بل الصداقة الرابعة: انضمَّ كريمُ للعصبةِ فصرنا أربعة. وستعرفون في قادمِ الحلقات… أيَّ جبالٍ حملَها معنا هذا الفتى القادمُ من زقاقٍ بعرضِ الكتفين.'}],
msg:'ادخلوا إخوةً لا زوّاراً: الشفقة تنظر من فوق والإخوة في العيون — والدموع التي لا تصير مشروعاً تجف وتُنسى.',apply:'حوّل تعاطفك إلى مشروع صغير: اجمع مع أصدقائك ثمن وجبة أو كتاب لطفل محتاج تعرفونه — وسلموه بكرامة.'},

{n:59,t:'رسالةٌ إلى توم',ic:'📮',age:'١٣ سنة',loc:'مكتب صلاح الدين — عمّان',corner:'social',goal:'الوفاء بالعهد عبر السنين: الصداقة الصادقة دعوة صامتة طويلة النفس',chars:['صلاح الدين','توم (صوته عبر الرسائل)'],
scenes:[
{h:'م١ · تحريك بصري — خريطة الرسائل',d:'حلقة بأسلوب مختلف كلياً (حلقة رسائلية): افتتاحية بصرية — خريطة قديمة الطراز تصل عمّان بمانشستر، وخيط ذهبي يعبرها ذهاباً وإياباً مع كل رسالة، والفصول تتغير على طرفي الخريطة: ثلج مانشستر / شمس عمّان. صوتا الصديقين يتناوبان قراءة الرسائل.',dlg:[['توم (صوته)','«عزيزي صلاح الدين… رسالتُكَ الأخيرةُ وصلتْ ومعها التمر — أمي خبأتْ نصفَهُ لنفسِها وأنكرتْ! سؤالُ هذا الشهر، ولا تضحك: أنتم تصلّون خمسَ مراتٍ كلَّ يوم… خمساً يا رجل! ألا تملّون؟ أنا بالكادِ أرتب سريري كلَّ يوم».']],vo:'إحدى عشرةَ سنةً من الرسائل بيني وبين توم… لكنَّ سنةَ الثالثةَ عشرةَ كانت أثقلَها ذهباً: السنةُ التي تحولتْ فيها أسئلتُهُ من «كيف حالُك؟»… إلى أسئلةِ القلوبِ الباحثة.'},
{h:'م٢ · داخلي — مكتب صلاح الدين، جواب الصلاة',d:'صلاح الدين يكتب على مكتبه ليلاً، بجانبه صورة توم وبوصلته النحاسية.',dlg:[['صلاح الدين (صوته يكتب)','«عزيزي توم… تسألُ: ألا نملّ؟ سأجيبُكَ بغيرِ الوعظ — بالوصف: تخيلْ يومَكَ نهراً يجرفُك: مدرسةٌ وضجيجٌ وواجباتٌ وشاشات. ثم — خمسَ مراتٍ في اليوم — تخرجُ من النهرِ إلى جزيرةٍ هادئة: تغسلُ وجهَكَ ويديك، وتقفُ أمامَ خالقِكَ وحدَكما، وتضعُ جبهتَكَ على الأرضِ وتقولُ له كلَّ شيء. خمسُ جزرٍ في نهرِ اليوم يا توم… نملُّ منها؟ نحن ننجو بها! جرِّبْ نسختَها عندك: توقفْ غداً خمسَ مراتٍ دقيقةً واحدة، واسألْ نفسَك: من أنا؟ وأين أمضي؟ ثم اكتبْ لي ماذا وجدت».'],['توم (رسالة الرد — صوته)','«…فعلتُها. خمسُ دقائقَ في اليوم أقفُ فيها عن الركض. النتيجةُ غريبة: وجدتُ أن أيامي تمضي وأنا لا أنتبهُ لها. صديقي… دينُكم هذا — أهو دينٌ أم فنُّ انتباه؟»']]},
{h:'م٣ · داخلي/خارجي — هدايا الأظرف',d:'مونتاج الهدايا الصغيرة عبر السنة — الدعوة تُلمس قبل أن تُقرأ: مع رسالة الشتاء يرسل صلاح الدين حفنة زعتر («رائحة بيت جدي»)، مع رسالة الربيع صورة العصبة أمام حديقة الأيدي الصغيرة، مع الصيف ورقة زيتون من الشجرة العتيقة. وتوم يرسل: ورقة قيقب حمراء («خريفنا الذي تحبه»)، صورة مسجد النور بعد توسعته، وقصاصة من جريدة المدرسة عن فوز صندوق غزة بجائزة العمل الخيري — يديره الآن هو وعمر وأنس.',dlg:[['توم (صوته)','«…وخبرُ الشهر: أنس ألقى كلمةً في احتفالِ المدرسةِ عن غزة، وذكرَ اسمَك — قال: البذرةُ الأولى غرسَها صديقٌ رحلَ شرقاً. المديرةُ بكت. وأنا فكرت: كم بذرةً زرعتَ هنا يا رجل وأنتَ لا تدري؟»']],vo:'زعترٌ وقيقبٌ وورقُ زيتون… يسميها الناسُ «هدايا صغيرة». وأنا أسميها بذوراً بريدية: تعبرُ البحارَ في أظرف، وتنبتُ في القلوبِ حيثُ لا تصلُ الخطب.'},
{h:'م٤ · داخلي — المكتب، سؤال «من هو محمد ﷺ؟»',d:'رسالة الخريف — الأثقل. صلاح الدين يقرؤها واقفاً ثم يجلس ببطء.',dlg:[['توم (صوته)','«صلاح الدين… وصلتُ في الكتابِ الذي أهديتَني إلى مواضعَ كثيرةٍ تذكرُ نبيَّكم محمداً. أنا أعرفُ عنه ما تقولُهُ صحفُنا — وهو قليلٌ وليس جميلاً دائماً. لكني تعلمتُ منكَ ألا آخذَ الحكاياتِ من خصومِها. فأسألُ صاحبي الذي لا يكذب: من هو محمدٌ عندَكم؟ لا تكتبْ لي فصلاً من كتاب… اكتبْ لي ما في قلبِكَ أنت».'],['صلاح الدين (يكتب — وصوته يتهدج قليلاً)','«يا توم… سألتَ عن أحبِّ الخلقِ إليَّ، فاسمحْ لي أن أجيبَ كطفلٍ لا كعالِم: هو الذي كانت أمي تحكي لي عنه كلَّ ليلةٍ فأبكي شوقاً وأنا في الثالثة. هو يتيمٌ رعى الغنمَ وما كذبَ قط — حتى لقَّبَهُ أعداؤهُ: الصادقَ الأمين. جاءتْهُ الدنيا فردَّها، وملكَ الجزيرةَ فرقعَ ثوبَهُ بيدِه، ودخلَ مكةَ فاتحاً منتصراً على من عذبوهُ عشرين سنة — فطأطأ رأسَهُ حتى لامسَ رحلَهُ تواضعاً، وقال: اذهبوا فأنتم الطلقاء. يا توم… أنا لا أتبعُهُ لأني وُلدتُ مسلماً فقط — أتبعُهُ لأني كلما كبرتُ وجربتُ الدنيا… وجدتُهُ أعظمَ مما ظننت. اقرأ سيرتَهُ من كتبِنا لا من صحفِكم… ثم احكمْ بقلبِكَ الإنجليزيِّ العادل — فأنا أعرفُ قلبَك: إنه من النوعِ الذي إذا رأى الحقَّ… لم يستطعْ أن يشيحَ عنه».']]},
{h:'م٥ · داخلي — المكتب، السطر الذي أسجد',d:'رسالة الشتاء الأخيرة تصل — أسمك من المعتاد. صلاح الدين يفتحها على مكتبه: صفحتان… وفي آخرها فقرة يقرؤها مرتين.',dlg:[['توم (صوته — بطيئاً)','«…وأخيراً، خبرٌ أرجوكَ أن تحفظَهُ بيننا — حتى أنا لا أفهمُهُ كاملاً بعد: ذهبتُ الأحدَ الماضي إلى مسجدِ النور. وحدي. جلستُ مع الشيخِ إدريس ساعةً — يا لهُ من رجلٍ يشبهُ وصفَك! سألتُهُ عنكَ وعن أشياءَ كثيرة. لا تخبرْ أحداً بعد… لكني بدأتُ أقرأ عن دينِكَ بجدية. لا أعدُكَ بشيء يا صديقي — أعدُكَ فقط أني أبحثُ بصدق. وأنتَ من علَّمني أن الصدقَ أولُ الطريق. جارُكَ دائماً — توم».'],['صلاح الدين','(يخفض الرسالة ببطء… يحدق في الفراغ ثانيتين… ثم ينزلق من كرسيه إلى الأرض ساجداً — سجدة شكر طويلة صامتة، والرسالة ما زالت في يده. يرفع رأسه ودموعه على السجادة) اللهم أتمم… يا ربَّ الفاتحة التي علمتُها له في حديقةِ أمِّه — أتمم.']],vo:'إحدى عشرةَ سنةً من صحنِ كعك، وسؤالٍ فوقَ أرجوحة، ومصحفٍ مترجم، وستينَ رسالة… وبذرةُ اللهِ تنبتُ في توقيتِها هي، لا في توقيتِنا. يا من تدعو صديقاً منذ سنين وتيأس: البذورُ الصادقةُ لا تموتُ يا صاحبي… بعضُها فقط يزهرُ متأخراً. فاصبرْ على بذورِك.'}],
msg:'الدعوة الصادقة بذور بريدية طويلة النفس: كن قدوةً تُلمس لا واعظاً يُسمع — والبذور الصادقة لا تموت بل تزهر متأخرة.',apply:'اكتب رسالة (ورقية أو صوتية) لصديق قديم لم تكلمه منذ زمن — اسأل عنه بصدق، وكن قدوة هادئة لا واعظاً ثقيلاً.'},

{n:60,t:'عهدُ المئذنة',ic:'🌙',age:'عيد ميلاده الثالث عشر',loc:'سطح مسجد الحي — عمّان',corner:'aqeeda',goal:'ميثاق البلوغ: من طفل مأمور إلى مكلَّف مسؤول — عهد شخصي مع الله يختم الطفولة',chars:['صلاح الدين','الشيخ محمود','أيوب','الجد'],
scenes:[
{h:'م١ · داخلي — بيت الجد، مفاجأة «لا حفلة»',d:'عصر عيد ميلاده الثالث عشر. صلاح الدين يعود من المدرسة متوقعاً رائحة كعك الجدة وبالونات يوسف… فيجد البيت هادئاً تماماً، وثلاثة رجال بانتظاره عند الباب بثياب الخروج: أبوه وجده والشيخ محمود.',dlg:[['صلاح الدين','(يتوقف مرتبكاً) …خير؟ أين الجميع؟ اليوم عيدُ—'],['أيوب','نعرف. ولهذا نحن هنا. الحفلةُ هذا العام… ليست حفلة. البسْ أجملَ ثيابِك وتوضأ — عندنا موعدٌ قبل المغرب.'],['الجد','(يبتسم ابتسامة غامضة ويمسك عصاه) ثلاثةَ عشرَ عاماً… انتهى زمنُ البالونات يا حبيبي. اليومَ طقسٌ آخر — طقسُ الرجال. كان أبي فعلَهُ معي على سطحٍ في القدس… وحان دورُك.']],vo:'توضأتُ ويداي ترتجفان قليلاً — من الرهبةِ لا الخوف. ثلاثةُ رجالٍ أحبُّهم أكثرَ من الدنيا، وموعدٌ غامض، وجملةُ «طقسُ الرجال»… أيُّ فتىً في الثالثةَ عشرةَ لا يرتجف؟'},
{h:'م٢ · خارجي — درج المئذنة ثم السطح، رهبة الصعود',d:'المسجد قبيل المغرب. الشيخ محمود يفتح باباً حديدياً صغيراً بجانب المحراب — درج حلزوني ضيق يصعد في جوف المئذنة. الأربعة يصعدون: الشيخ أولاً، ثم الفتى، والأب والجد (يصعد الجد ببطء متوكئاً — ويرفض المساعدة: «هذا الدرجُ أصعدُهُ بقدمَيَّ ولو زحفاً»). ينفتح السطح: عمّان كلها تحت الغروب — تلال بيوت متدرجة، ومآذن تتوزع كسواري سفن، وأفق غربي يحترق ذهباً.',dlg:[['الشيخ محمود','(يقف بهم عند السور الغربي) انظرْ يا صلاحَ الدين… من هنا أطلقتُ الأذانَ أربعين سنة. وعلى هذا السطحِ أصعدُ بفتيانٍ مخصوصين — واحداً كلَّ بضعِ سنين — حين يبلغون مبلغَ الرجال. اجلسوا… فالكلامُ الثقيلُ يُقالُ جلوساً.']]},
{h:'م٣ · خارجي — السطح، حوار التكليف',d:'الأربعة جلوس على بساط صغير حمله الشيخ. الغروب يتقدم. حوار المشهد المحوري — بإيقاع هادئ مهيب.',dlg:[['الشيخ محمود','يا صلاحَ الدين… أتعرفُ ماذا حدثَ لكَ هذا العام — لا في جسدِكَ بل في السماء؟ (يشير للأعلى) القلمُ جرى. حتى الأمسِ كانت صلاتُكَ تطوعاً وصيامُكَ تدريباً وحسناتُكَ تُكتَبُ وسيئاتُكَ تُمحى — كنتَ ضيفاً معفياً. من اليوم… فُتحَ ملفُّك: تُكتَبُ لكَ وعليك. صلاتُكَ اليومَ دينُكَ أنت — لا دينُ أبيك. أفهمتَ الفرق؟'],['صلاح الدين','(بصوت خفيض) فهمت… يعني لم أعدْ أصلي لأنكم علمتموني… أصلي لأني أنا العبد. الحسابُ حسابي… والاختيارُ اختياري.'],['أيوب','(يتدخل بحنان) ولا يعني أنكَ وحدُك — نحن خلفَكَ ما حيينا. يعني فقط أن يدي لم تعدْ تحملُك… صارت تصافحُك. (يمد يده ويصافحه مصافحة الرجال — لقطة قريبة على اليدين)'],['الجد','(يعتدل… ويخرج المفتاح من صدره ببطء مهيب — ثم يفعل ما انتظرته السلسلة: يعلقه بخيطه الصوفي حول رقبة الحفيد) وهذه… عهدتُك الأولى. ليس هديةَ عيدٍ يا صلاحَ الدين — أمانةٌ أسلِّمُها لمكلَّفٍ يُكتَبُ عملُه. احملْهُ حتى تسلِّمَهُ لبابِه… أو لمن يفتحُ البابَ إن سبقتُكَ إلى الله. (يشد الخيط على صدر الفتى) صارَ قلبُكَ ومفتاحي جارين… فليتعلمْ كلٌّ منهما من صاحبِه: القلبُ يتعلمُ الصلابة… والمفتاحُ يتعلمُ النبض.']],vo:'ثقلُ الحديدِ على صدري… ما زلتُ أشعرُ به كلما أغمضتُ عيني. ليس ثقلَ معدنٍ — ثقلُ ثمانين سنةً من الانتظار، وبيتٍ حجريٍّ يذكرُ ساكنيه، وجدٍّ يسلمُ عمرَهُ كلَّهُ في خيطِ صوف.'},
{h:'م٤ · خارجي — السطح، كتابة العهد',d:'الشيخ محمود يخرج من عباءته دفتراً جلدياً صغيراً جديداً وقلم حبر.',dlg:[['الشيخ محمود','والآن ركنُ الطقسِ الأخير. كلُّ فتىً أصعدتُهُ هذا السطحَ كتبَ بخطِّ يدِه «عهدَهُ» — ثلاثةُ سطورٍ بينَهُ وبين الله: عبادةٌ يلتزمُها، وخلقٌ يبنيه، وحلمٌ يخدمُ به أمتَه. لا نمليها عليك… العهدُ المملى ليس عهداً. خذِ الدفترَ وامشِ إلى تلك الزاوية — بينكَ وبين ربِّكَ والغروب.'],['صلاح الدين','(يمشي للزاوية الغربية وحده… يقف طويلاً والقلم في يده وعمّان تحته والأفق الذهبي أمامه… ثم يكتب. نرى الخط الفتي على الورق، سطراً سطراً) «عهدُ صلاحِ الدين — كُتبَ على سطحِ المئذنةِ يومَ بلغَ: أولاً: أعبدُ اللهَ وحدَهُ لا أشركُ به شيئاً… وأحرسُ فجري ما حييت. ثانياً: أبني نفسي كلَّ يومٍ — حفظاً وعلماً وقوةً وخلقاً — لأني لبنةٌ في جدارِ أمتي، واللبنةُ الضعيفةُ تسقطُ الجدار. ثالثاً: أحملُ المفتاحَ الذي على صدري… حتى يفتحَ اللهُ بنا أو بجيلٍ نعدُّهُ البابَ الذي ينتظر. واللهُ على ما أقولُ شهيد». (يوقع باسمه)']],},
{h:'م٥ · خارجي — السطح، الأذان تحت الأقدام',d:'يعود بالدفتر. الشيخ يقرأ العهد صامتاً… يرفع رأسه بعينين لامعتين، يطوي الدفتر ويعيده للفتى: «يبقى معك — يُقرأُ كلَّ عيدِ ميلاد». وفي اللحظة نفسها يحين المغرب: الشيخ يعتذر — «أذاني الأخيرُ قبل التقاعدِ قريب… لكن اليومَ أريدُ أن يؤذنَ السطحُ بصوتٍ أصغر». يلتفت لصلاح الدين ويشير لمكبر الصوت.',dlg:[['صلاح الدين','(مصعوقاً) أنا؟! أؤذنُ من المئذنة؟!'],['الشيخ محمود','مكلَّفٌ… حاملُ عهدٍ… وصوتُهُ حسن. من غيرُك؟ اللهُ أكبر يا بني — أطلِقْها.'],['صلاح الدين','(يقف أمام المكبر، يغمض عينيه، المفتاح على صدره والدفتر في جيبه… ويرفع أذانَ المغرب — صوت فتيّ يتكسر في «أشهد» الأولى ثم يستوي ويتصاعد ويملأ الحارة. تحته: الجدة تسمع من شرفة البيت وتضع يدها على فمها، مريم تبكي في المطبخ، حمزة ومعاذ يتوقفان في الشارع ويرفعان رأسيهما للمئذنة مذهولين: «هذا…؟!»، وأبو سليم العجوز يبتسم عند نافذته)'],['الجد','(على السطح، يهمس لأيوب والأذان يتردد في التلال) اسمعْهُ يا أيوب… صبيٌّ صعدَ هذا الدرج. (يمسح دمعته بكوفيته) ورجلٌ سينزلُه.']],vo:'وهكذا خُتمتْ طفولتي — لا بشمعةٍ تُطفأ… بأذانٍ يُرفَع. نزلتُ الدرجَ الحلزونيَّ ذلك المساءَ وأنا غيرُ الذي صعدَه: على صدري مفتاح، وفي جيبي عهدٌ بخطِّ يدي، وفي أذنيَّ صدى صوتي يملأ السماء. انتهتِ المرحلةُ يا أصدقائي… وبدأ زمنُ البناءِ الحق. فمن منكم يكتبُ عهدَهُ الليلة؟'}],
msg:'جرى القلم وفُتح الملف: صلاتك دينك لا دين أبيك — فاكتب عهدك بيدك: عبادة تلتزمها وخلق تبنيه وحلم تخدم به أمتك.',apply:'اكتب «عهدك» بخط يدك: ثلاثة سطور بينك وبين الله — عبادة تلتزمها، وخُلق تبنيه، وحلم تخدم به أمتك. وقّعه وعلّقه.'}
]});
